window.QB_TKP_B19 = [
{"id":"TKP-3301", "q":"Teman seangkatan latsar CPNS mengajak Anda bergabung ke grup belajar yang ternyata berisi doktrin bahwa sistem khilafah wajib menggantikan NKRI. Sikap Anda?", "opts":[{"t":"Menolak tegas dan melaporkan grup tersebut ke penyelenggara latsar/BKPSDM agar ditindaklanjuti.","s":5},{"t":"Menolak bergabung dan menasihati teman agar keluar dari grup itu.","s":4},{"t":"Menolak ajakan namun diam saja tanpa melapor ke siapa pun.","s":3},{"t":"Tetap di grup dengan alasan menjaga pertemanan seangkatan.","s":2},{"t":"Ikut bergabung karena materinya terlihat meyakinkan.","s":1}], "ex":"ASN wajib menolak paham khilafah dan melaporkannya lewat jalur resmi; diam saja berarti membiarkan radikalisasi di lingkungan ASN."},
{"id":"TKP-3302", "q":"Sebagai admin website desa, Anda mendapati situs resmi desa diretas dan disisipi banner propaganda kelompok ekstrem. Tindakan Anda?", "opts":[{"t":"Menurunkan kontennya segera, mengamankan situs, lalu melaporkan peretasan ke atasan dan aparat berwenang.","s":5},{"t":"Menghapus banner propaganda dan mengganti password admin situs.","s":4},{"t":"Membiarkan dulu sampai ada perintah dari atasan.","s":3},{"t":"Menganggapnya ulah iseng dan tidak berbuat apa-apa.","s":2},{"t":"Membiarkannya tayang karena takut diserang balik peretasnya.","s":1}], "ex":"Fasilitas digital negara tidak boleh menjadi corong propaganda ekstrem; admin wajib menertibkan dan melapor ke aparat."},
{"id":"TKP-3303", "q":"Vendor pemenang proyek menawarkan 'fee' yang akan disalurkan ke yayasan yang Anda ketahui terafiliasi jaringan radikal. Sikap Anda sebagai PPK?", "opts":[{"t":"Menolak tegas dan melaporkan tawaran itu ke atasan/inspektorat sebagai indikasi gratifikasi dan pendanaan ekstremisme.","s":5},{"t":"Menolak fee tersebut dan memperingatkan vendor agar tidak mengulanginya.","s":4},{"t":"Menolak fee-nya saja tanpa melaporkan yayasannya.","s":3},{"t":"Menerima fee karena menganggapnya urusan pribadi vendor.","s":2},{"t":"Menerima fee dan ikut menyalurkan ke yayasan tersebut.","s":1}], "ex":"Gratifikasi untuk jaringan radikal adalah korupsi sekaligus pendanaan ekstremisme; wajib ditolak dan dilaporkan resmi."},
{"id":"TKP-3304", "q":"Widyaiswara dalam diklat Anda menyelipkan materi ceramah bernada intoleran yang menghasut peserta memusuhi kelompok berbeda keyakinan. Tindakan Anda?", "opts":[{"t":"Melaporkan materi menyimpang itu ke penyelenggara diklat/BKPSDM agar dievaluasi resmi.","s":5},{"t":"Menyampaikan keberatan langsung kepada widyaiswara yang bersangkutan.","s":4},{"t":"Diam saja karena takut nilai diklat Anda terpengaruh.","s":3},{"t":"Menganggapnya bagian dari kebebasan berpendapat pemateri.","s":2},{"t":"Menyebarkan materi itu ke peserta lain karena setuju isinya.","s":1}], "ex":"Diklat ASN tidak boleh disusupi paham intoleran; peserta wajib melapor lewat jalur resmi, bukan membiarkan."},
{"id":"TKP-3305", "q":"Di ruang tunggu puskesmas, seorang pengunjung memutar ceramah ekstrem yang provokatif dan mengajak pasien memusuhi pemerintah. Anda petugas di sana. Tindakan Anda?", "opts":[{"t":"Menghentikan pemutaran, menegur pengunjung, dan melaporkan ke pimpinan puskesmas/aparat bila berlanjut.","s":5},{"t":"Meminta pengunjung mematikan ceramah karena mengganggu pelayanan.","s":4},{"t":"Membiarkan karena menganggapnya urusan pribadi pengunjung.","s":3},{"t":"Pura-pura tidak mendengar agar tidak ribut.","s":2},{"t":"Ikut menyimak karena isi ceramahnya menarik.","s":1}], "ex":"Fasilitas pelayanan publik wajib steril dari propaganda ekstrem; petugas harus menertibkan dan melapor bila perlu."},
{"id":"TKP-3306", "q":"Sopir kendaraan dinas selalu memutar ceramah kelompok ekstrem yang anti-pemerintah setiap perjalanan dinas bersama Anda. Sikap Anda?", "opts":[{"t":"Meminta sopir mematikan dan melaporkan kebiasaannya ke atasan bila ia menolak.","s":5},{"t":"Menegur sopir agar tidak memutar ceramah seperti itu saat dinas.","s":4},{"t":"Diam saja dan memakai earphone sendiri.","s":3},{"t":"Membiarkan karena sopir lebih senior dari Anda.","s":2},{"t":"Ikut mendengarkan dan membenarkan isi ceramahnya.","s":1}], "ex":"Kendaraan dinas adalah fasilitas negara; ASN tidak boleh membiarkannya dipakai menyebarkan paham ekstrem."},
{"id":"TKP-3307", "q":"Anda mengetahui dana koperasi pegawai dipakai pengurus untuk donasi ke 'front perjuangan' yang terafiliasi jaringan radikal, tanpa sepengetahuan anggota. Tindakan Anda?", "opts":[{"t":"Melaporkan penyalahgunaan dana itu ke pengawas koperasi dan pimpinan agar diaudit resmi.","s":5},{"t":"Memprotes pengurus dalam rapat anggota dan menuntut pertanggungjawaban.","s":4},{"t":"Keluar dari koperasi tanpa mempersoalkan dana tersebut.","s":3},{"t":"Membiarkan karena menganggapnya urusan pengurus.","s":2},{"t":"Ikut menyumbang karena tujuannya terlihat mulia.","s":1}], "ex":"Dana bersama tidak boleh diselewengkan untuk jaringan radikal; anggota wajib menuntut audit dan melapor."},
{"id":"TKP-3308", "q":"Kotak amal di musholla kantor ternyata disalurkan pengelolanya ke jaringan kelompok ekstrem. Anda mengetahuinya. Tindakan Anda?", "opts":[{"t":"Melaporkan penyelewengan itu ke pimpinan dan aparat agar diusut tuntas.","s":5},{"t":"Menegur pengelola dan meminta penyaluran dihentikan.","s":4},{"t":"Berhenti beramal di kotak itu tanpa berbuat lebih jauh.","s":3},{"t":"Tetap beramal dengan alasan niatnya yang penting.","s":2},{"t":"Ikut menggalang dana untuk penyaluran tersebut.","s":1}], "ex":"Amal yang diselewengkan ke jaringan ekstrem adalah pendanaan terorisme; wajib dilaporkan ke aparat."},
{"id":"TKP-3309", "q":"Pelatih klub futsal antar-pegawai ternyata merekrut anggota menjadi 'sel' kelompok ekstrem berkedok pembinaan mental. Sikap Anda sebagai anggota klub?", "opts":[{"t":"Keluar dari klub dan melaporkan perekrutan itu ke pimpinan/aparat.","s":5},{"t":"Menolak ikut dan memperingatkan rekan-rekan satu klub.","s":4},{"t":"Berhenti ikut latihan tanpa menjelaskan alasan.","s":3},{"t":"Tetap ikut main dengan alasan hanya untuk olahraga.","s":2},{"t":"Ikut bergabung karena iming-iming solidaritasnya kuat.","s":1}], "ex":"Rekrutmen berkedok komunitas adalah modus umum jaringan ekstrem; ASN wajib menolak dan melapor."},
{"id":"TKP-3310", "q":"Buletin internal kantor memuat artikel kiriman 'pembaca' yang isinya ujaran intoleran terhadap kelompok agama tertentu. Anda bagian humas. Tindakan Anda?", "opts":[{"t":"Menarik artikel itu dari peredaran dan melaporkan penulisnya ke pimpinan untuk dibina.","s":5},{"t":"Meminta redaksi mencabut artikel dan membuat klarifikasi.","s":4},{"t":"Membiarkan karena sudah terlanjur dicetak.","s":3},{"t":"Menganggapnya sekadar opini pembaca yang sah-sah saja.","s":2},{"t":"Ikut membagikan buletin itu ke pihak luar.","s":1}], "ex":"Media resmi instansi tidak boleh memuat ujaran intoleran; humas wajib menarik dan menindaklanjutinya."},
{"id":"TKP-3311", "q":"Tetangga Anda yang TKI purna pulang membawa paham radikal dari luar negeri dan mulai mengajak warga sekitar, termasuk keluarga Anda. Sikap Anda?", "opts":[{"t":"Menolak ajakannya, melindungi keluarga, dan melaporkan aktivitasnya ke aparat desa/Bhabinkamtibmas.","s":5},{"t":"Menasihati tetangga agar tidak menyebarkan paham itu di lingkungan.","s":4},{"t":"Melarang keluarga ikut namun tidak melapor ke siapa pun.","s":3},{"t":"Membiarkan karena menganggapnya urusan keyakinan pribadi.","s":2},{"t":"Ikut kajiannya karena penasaran pengalaman dari luar negeri.","s":1}], "ex":"Paham radikal impor sama berbahayanya; warga wajib menolak dan melapor ke aparat agar dicegah penyebarannya."},
{"id":"TKP-3312", "q":"Panitia donasi bencana di kantor Anda ketahuan menyelewengkan sebagian dana untuk 'dana jihad' kelompok teroris. Tindakan Anda?", "opts":[{"t":"Melaporkan penyelewengan itu ke pimpinan dan aparat penegak hukum segera.","s":5},{"t":"Mendesak panitia mengembalikan dana dan menghentikan penyaluran.","s":4},{"t":"Berhenti berdonasi tanpa mempersoalkan penyelewengannya.","s":3},{"t":"Tetap berdonasi dengan alasan niat membantu korban.","s":2},{"t":"Ikut menggalang karena tidak tahu-menahu soal penyalurannya.","s":1}], "ex":"Donasi bencana yang diselewengkan ke teroris adalah kejahatan serius; wajib dilaporkan ke aparat."},
{"id":"TKP-3313", "q":"Sebagai penghulu KUA, Anda menemukan calon pengantin terindikasi anggota jaringan ekstrem, dan keluarganya menekan agar pernikahan tetap dilangsungkan. Sikap Anda?", "opts":[{"t":"Tetap menjalankan prosedur, mencatat temuan, dan melaporkan indikasi itu ke atasan/aparat berwenang.","s":5},{"t":"Menunda pencatatan sambil berkoordinasi dengan pimpinan KUA.","s":4},{"t":"Melangsungkan saja karena tugas Anda hanya pencatatan.","s":3},{"t":"Menuruti tekanan keluarga agar tidak ribut.","s":2},{"t":"Membantu menutupi identitasnya dari aparat.","s":1}], "ex":"ASN wajib menjalankan prosedur sekaligus melaporkan indikasi ekstremisme; tekanan pihak mana pun tidak boleh ditaati."},
{"id":"TKP-3314", "q":"Sebagai enumerator survei, Anda mendapati responden yang door-to-door menyebarkan paham khilafah sambil mengisi kuesioner. Tindakan Anda?", "opts":[{"t":"Menyelesaikan tugas secara profesional dan melaporkan temuan itu ke koordinator/aparat setempat.","s":5},{"t":"Menasihati responden agar tidak mencampur survei dengan penyebaran paham.","s":4},{"t":"Fokus ke kuesioner saja dan mengabaikan temuannya.","s":3},{"t":"Mendengarkan ceramahnya karena menghormati responden.","s":2},{"t":"Ikut menyebarkan selebarannya ke rumah responden lain.","s":1}], "ex":"Temuan penyebaran paham khilafah saat bertugas wajib dilaporkan; profesionalitas tidak berarti tutup mata."},
{"id":"TKP-3315", "q":"Guru TPQ di lingkungan Anda mengajarkan anak-anak lagu bernada intoleran yang menghina kelompok berbeda keyakinan. Anda wali salah satu murid. Sikap Anda?", "opts":[{"t":"Melaporkan materi itu ke pengelola TPQ/tokoh masyarakat agar dievaluasi dan diganti.","s":5},{"t":"Menegur guru TPQ dan meminta lagu itu tidak diajarkan lagi.","s":4},{"t":"Memindahkan anak ke TPQ lain tanpa mempersoalkan.","s":3},{"t":"Membiarkan karena menganggapnya bagian dari pembelajaran agama.","s":2},{"t":"Mendukung karena lagunya dianggap membangkitkan semangat.","s":1}], "ex":"Anak-anak tidak boleh dicekoki ujaran intoleran; orang tua wajib bertindak lewat jalur yang tepat."},
{"id":"TKP-3316", "q":"Linmas diajak ronda gabungan antar-RT yang ternyata dimanfaatkan untuk mobilisasi massa intoleran menolak rumah ibadah kelompok minoritas. Anda anggota linmas. Sikap Anda?", "opts":[{"t":"Menolak ikut mobilisasi dan melaporkan rencana itu ke lurah/Bhabinkamtibmas.","s":5},{"t":"Menasihati koordinator ronda agar tidak mencampur tugas keamanan dengan aksi intoleran.","s":4},{"t":"Tidak ikut namun diam saja.","s":3},{"t":"Ikut ronda dengan alasan menjaga keamanan saja.","s":2},{"t":"Ikut memobilisasi karena perintah koordinator.","s":1}], "ex":"Aparat keamanan lingkungan tidak boleh dipakai untuk aksi intoleran; wajib menolak dan melapor."},
{"id":"TKP-3317", "q":"Majelis taklim ibu-ibu PKK mulai disusupi penceramah yang menyebarkan paham intoleran dan ajakan memusuhi pemerintah. Anda pengurus PKK. Tindakan Anda?", "opts":[{"t":"Menghentikan penceramah itu dan melaporkan ke ketua PKK/tokoh masyarakat/aparat.","s":5},{"t":"Mengganti penceramah dengan yang jelas rekam jejaknya.","s":4},{"t":"Tidak hadir lagi tanpa menjelaskan alasan.","s":3},{"t":"Tetap hadir dengan alasan silaturahmi.","s":2},{"t":"Ikut menyebarkan rekaman ceramahnya ke grup lain.","s":1}], "ex":"Pengajian tidak boleh menjadi corong paham intoleran; pengurus wajib menertibkan dan melapor."},
{"id":"TKP-3318", "q":"Komunitas ojek online di pangkalan dekat kantor mengajak Anda 'kopdar' yang ternyata berisi baiat sumpah setia ke kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan kegiatan baiat itu ke aparat berwenang.","s":5},{"t":"Menasihati pengajak agar tidak menyeret komunitas ke paham ekstrem.","s":4},{"t":"Menolak halus tanpa melapor.","s":3},{"t":"Datang sekadar nongkrong tanpa ikut baiat.","s":2},{"t":"Ikut baiat karena sungkan pada komunitas.","s":1}], "ex":"Baiat ke kelompok ekstrem adalah pintu masuk terorisme; wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3319", "q":"TV di kantin kantor setiap istirahat memutar video ceramah kelompok ekstrem yang provokatif. Anda pegawai yang makan di sana. Tindakan Anda?", "opts":[{"t":"Meminta pengelola kantin menghentikan dan melaporkan bila ia menolak.","s":5},{"t":"Menegur pengelola agar mengganti tontonan yang netral.","s":4},{"t":"Pindah makan ke tempat lain tanpa protes.","s":3},{"t":"Membiarkan karena bukan wewenang Anda.","s":2},{"t":"Ikut menonton karena videonya ramai dibicarakan.","s":1}], "ex":"Ruang publik kantor wajib steril dari propaganda ekstrem; pegawai berhak menuntut penertiban."},
{"id":"TKP-3320", "q":"Satpam kantor ketahuan menyimpan selebaran propaganda khilafah di pos jaga dan membagikannya ke tamu. Anda mengetahuinya. Tindakan Anda?", "opts":[{"t":"Melaporkan temuan itu ke atasan/vendor keamanan agar ditindak resmi.","s":5},{"t":"Menegur satpam dan meminta selebarannya dimusnahkan.","s":4},{"t":"Mengabaikan karena satpam bukan PNS.","s":3},{"t":"Membiarkan dengan alasan kasihan pada satpam.","s":2},{"t":"Ikut mengambil selebarannya untuk dibaca.","s":1}], "ex":"Siapa pun di lingkungan kantor yang menyebar paham khilafah wajib ditertibkan lewat jalur resmi."},
{"id":"TKP-3321", "q":"Siswa magang PKL di unit Anda menyebarkan paham intoleran di grup chat magang. Anda pembimbingnya. Tindakan Anda?", "opts":[{"t":"Menegur dan membina siswa itu, serta melaporkan ke sekolah/instansi bila berlanjut.","s":5},{"t":"Memberi pembinaan langsung agar berhenti menyebarkan paham itu.","s":4},{"t":"Mengeluarkannya dari grup chat saja.","s":3},{"t":"Membiarkan karena ia hanya anak magang sementara.","s":2},{"t":"Ikut menimpali dengan candaan agar akrab.","s":1}], "ex":"Pembimbing wajib membina siswa magang yang terpapar paham intoleran, bukan membiarkannya."},
{"id":"TKP-3322", "q":"Pengajian lansia di posyandu disusupi ajakan intoleran yang menghasut peserta memusuhi tetangga beda keyakinan. Anda kader posyandu. Sikap Anda?", "opts":[{"t":"Menghentikan ajakan itu dan melaporkan penceramahnya ke tokoh masyarakat.","s":5},{"t":"Menegur penceramah agar kembali ke materi keagamaan yang damai.","s":4},{"t":"Tidak mengajak orang tua Anda lagi tanpa protes.","s":3},{"t":"Membiarkan karena pesertanya orang tua-tua.","s":2},{"t":"Ikut menyebarkan ajakannya ke grup keluarga.","s":1}], "ex":"Kelompok rentan seperti lansia tidak boleh menjadi sasaran hasutan intoleran; kader wajib bertindak."},
{"id":"TKP-3323", "q":"Turnamen e-sport antar-instansi disponsori 'komunitas' yang ternyata front rekrutmen kelompok radikal. Anda panitia. Tindakan Anda?", "opts":[{"t":"Membatalkan kerja sama sponsor dan melaporkan komunitas itu ke pimpinan/aparat.","s":5},{"t":"Mengganti sponsor dengan pihak yang jelas legalitasnya.","s":4},{"t":"Tetap memakai sponsornya karena dananya sudah cair.","s":3},{"t":"Membiarkan karena menganggapnya sekadar sponsor biasa.","s":2},{"t":"Ikut mempromosikan komunitas itu ke peserta.","s":1}], "ex":"Kegiatan resmi tidak boleh didanai front kelompok radikal; panitia wajib memutus kerja sama dan melapor."},
{"id":"TKP-3324", "q":"Grup WhatsApp alumni SMA menggalang dana untuk 'membela mujahid' yang ternyata narapidana terorisme. Anda anggota grup. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan penggalangan itu ke aparat karena mendanai terorisme.","s":5},{"t":"Menasihati admin grup agar menghentikan penggalangan.","s":4},{"t":"Keluar dari grup tanpa berkomentar.","s":3},{"t":"Tetap di grup dengan alasan nostalgia.","s":2},{"t":"Ikut berdonasi karena kasihan.","s":1}], "ex":"Dana untuk narapidana terorisme adalah pendanaan terorisme; wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3325", "q":"Tukang fotokopi langganan kantor menyelipkan selebaran propaganda khilafah di setiap bundel fotokopian dinas. Anda mengetahuinya. Tindakan Anda?", "opts":[{"t":"Melaporkan ke atasan agar vendor dievaluasi dan selebarannya dimusnahkan.","s":5},{"t":"Menegur pemilik fotokopian agar berhenti menyelipkan selebaran.","s":4},{"t":"Membuang selebarannya diam-diam tiap menerima bundel.","s":3},{"t":"Mengabaikan karena hanya selebaran.","s":2},{"t":"Membaca dan membagikannya ke rekan.","s":1}], "ex":"Dokumen dinas tidak boleh disusupi propaganda khilafah; temuan wajib dilaporkan agar vendor ditindak."}
,
{"id":"TKP-3326", "q":"Komunitas gaming Discord yang Anda ikuti mengadakan turnamen berhadiah yang ternyata syaratnya mengikuti 'pembinaan' paham ekstrem. Sikap Anda?", "opts":[{"t":"Keluar dari komunitas dan melaporkan modus rekrutmen itu ke aparat.","s":5},{"t":"Menolak ikut pembinaan dan memperingatkan anggota lain.","s":4},{"t":"Tetap main game-nya saja tanpa ikut pembinaan.","s":3},{"t":"Ikut pembinaan sekadar formalitas demi hadiahnya.","s":2},{"t":"Mengikuti pembinaan dan ikut menyebarkannya.","s":1}], "ex":"Rekrutmen berkedok komunitas hobi adalah modus jaringan ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3327", "q":"Anda menemukan lowongan kerja palsu yang ternyata kedok rekrutmen kelompok radikal — pelamar diminta 'baiat' sebelum diterima. Tindakan Anda?", "opts":[{"t":"Melaporkan lowongan palsu itu ke aparat dan platform penyebar info loker.","s":5},{"t":"Menyebarkan peringatan ke grup pencari kerja agar tidak tertipu.","s":4},{"t":"Mengabaikan karena Anda tidak sedang cari kerja.","s":3},{"t":"Mencoba melamar untuk melihat-lihat saja.","s":2},{"t":"Ikut baiat demi mendapatkan pekerjaan.","s":1}], "ex":"Rekrutmen berkedok lowongan kerja menjebak korban; wajib dilaporkan agar tidak ada korban lanjutan."},
{"id":"TKP-3328", "q":"Seminar motivasi 'self-help' yang Anda hadiri ternyata disisipi doktrin ekstrem yang menghasut peserta memusuhi pemerintah. Sikap Anda?", "opts":[{"t":"Meninggalkan seminar dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menegur panitia agar menghentikan doktrin tersebut.","s":4},{"t":"Pulang diam-diam tanpa berbuat apa-apa.","s":3},{"t":"Tetap mengikuti sampai selesai karena sudah bayar.","s":2},{"t":"Ikut menyebarkan materi seminar ke orang lain.","s":1}], "ex":"Doktrin ekstrem berkedok seminar motivasi tetap berbahaya; peserta wajib menolak dan melapor."},
{"id":"TKP-3329", "q":"Rekan menawarkan investasi dengan imbal hasil besar berkedok 'ekonomi perjuangan khilafah', dan dananya disalurkan ke jaringan kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan skema itu ke aparat sebagai penipuan dan pendanaan ekstremisme.","s":5},{"t":"Menolak ikut dan memperingatkan rekan tentang bahayanya.","s":4},{"t":"Menolak halus tanpa melapor.","s":3},{"t":"Ikut dengan modal kecil untuk coba-coba.","s":2},{"t":"Ikut berinvestasi karena imbal hasilnya menggiurkan.","s":1}], "ex":"Investasi berkedok perjuangan adalah penipuan sekaligus pendanaan ekstremisme; wajib ditolak dan dilaporkan."},
{"id":"TKP-3330", "q":"Biro travel menawarkan umroh super murah dengan syarat mengikuti 'kajian khusus' yang ternyata rekrutmen paham radikal. Sikap Anda?", "opts":[{"t":"Membatalkan keberangkatan dan melaporkan biro itu ke aparat.","s":5},{"t":"Menolak kajian dan meminta travel mengganti dengan program normal.","s":4},{"t":"Tetap berangkat tapi tidak ikut kajiannya.","s":3},{"t":"Ikut kajiannya sekadar formalitas.","s":2},{"t":"Mengikuti kajian dan ikut menyebarkannya.","s":1}], "ex":"Ibadah tidak boleh dijadikan kedok rekrutmen paham radikal; biro seperti itu wajib dilaporkan."},
{"id":"TKP-3331", "q":"Seorang pria yang baru dikenal menawarkan pernikahan siri kepada kerabat perempuan Anda sebagai syarat masuk 'jamaah perjuangan' berpaham ekstrem. Sikap Anda?", "opts":[{"t":"Mencegah pernikahan itu dan melaporkan modus perekrutan ke aparat/keluarga.","s":5},{"t":"Menasihati kerabat agar tidak terjebak bujuk rayu tersebut.","s":4},{"t":"Menyerahkan keputusan sepenuhnya pada kerabat.","s":3},{"t":"Mendukung karena menganggapnya urusan pribadi.","s":2},{"t":"Ikut membantu melancarkan pernikahan itu.","s":1}], "ex":"Pernikahan dijadikan alat rekrutmen ekstremisme adalah kejahatan; wajib dicegah dan dilaporkan."},
{"id":"TKP-3332", "q":"Seorang mengaku wartawan memeras instansi Anda: bila tidak diberi uang, ia akan menulis berita bernada SARA dan intoleran. Sikap Anda?", "opts":[{"t":"Menolak tegas dan melaporkan pemerasan ke pimpinan serta aparat penegak hukum.","s":5},{"t":"Menolak memberi uang dan meminta ia menunjukkan identitas pers resmi.","s":4},{"t":"Mengabaikan ancamannya.","s":3},{"t":"Memberi sedikit uang agar tidak ribut.","s":2},{"t":"Memberi uang sesuai permintaannya.","s":1}], "ex":"Pemerasan berkedok jurnalisme dengan isu SARA wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3333", "q":"LSM asing menawarkan hibah besar ke unit Anda dengan syarat memasukkan agenda intoleran dalam program pemberdayaan. Sikap Anda?", "opts":[{"t":"Menolak hibah dan melaporkan tawaran itu ke pimpinan/instansi berwenang.","s":5},{"t":"Menolak syaratnya dan meminta kerja sama yang bersih dari agenda tersembunyi.","s":4},{"t":"Menunda keputusan tanpa melapor.","s":3},{"t":"Menerima dengan alasan dana untuk masyarakat.","s":2},{"t":"Menerima dan menjalankan agendanya.","s":1}], "ex":"Dana asing tidak boleh menjadi pintu masuk agenda intoleran; tawaran seperti itu wajib ditolak dan dilaporkan."},
{"id":"TKP-3334", "q":"Aksi donor darah massal di kantor ternyata dipakai panitia untuk mendata dan merekrut pendonor ke kelompok berpaham ekstrem. Anda mengetahuinya. Tindakan Anda?", "opts":[{"t":"Melaporkan modus itu ke pimpinan dan aparat agar dihentikan.","s":5},{"t":"Menegur panitia dan meminta pendataan dihentikan.","s":4},{"t":"Tidak ikut donor lagi tanpa protes.","s":3},{"t":"Tetap donor dengan alasan kemanusiaan.","s":2},{"t":"Ikut mengisi data dan bergabung.","s":1}], "ex":"Kegiatan kemanusiaan tidak boleh dijadikan kedok rekrutmen ekstrem; modusnya wajib dilaporkan."},
{"id":"TKP-3335", "q":"Komunitas pendaki gunung yang Anda ikuti diajak 'jihad alam' oleh seniornya — latihan fisik yang ternyata persiapan aksi teror. Sikap Anda?", "opts":[{"t":"Keluar dari komunitas dan melaporkan kegiatan itu ke aparat.","s":5},{"t":"Menolak ikut latihan dan memperingatkan anggota lain.","s":4},{"t":"Berhenti ikut pendakian tanpa menjelaskan.","s":3},{"t":"Tetap ikut mendaki dengan alasan hobi.","s":2},{"t":"Ikut latihan fisiknya karena dianggap seru.","s":1}], "ex":"Pelatihan fisik berkedok hobi untuk persiapan teror wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3336", "q":"Kontrakan di lingkungan Anda dijadikan markas kajian tertutup yang mengajarkan paham khilafah dan kebencian pada pemerintah. Anda ketua RT. Tindakan Anda?", "opts":[{"t":"Melaporkan aktivitas mencurigakan itu ke lurah/Bhabinkamtibmas untuk ditindaklanjuti.","s":5},{"t":"Mendatangi pemilik kontrakan dan meminta kegiatan dihentikan.","s":4},{"t":"Membiarkan karena penyewanya membayar tepat waktu.","s":3},{"t":"Menganggapnya urusan pribadi penyewa.","s":2},{"t":"Ikut menghadiri kajiannya karena penasaran.","s":1}], "ex":"Ketua lingkungan wajib melaporkan aktivitas kajian tertutup berpaham khilafah ke aparat."},
{"id":"TKP-3337", "q":"Barbershop langganan Anda memutar ceramah intoleran yang provokatif dan menempel selebaran propaganda khilafah di cermin. Sikap Anda?", "opts":[{"t":"Menegur pemilik dan melaporkan bila ia menolak menertibkan usahanya.","s":5},{"t":"Meminta pemilik mematikan ceramah dan mencopot selebaran.","s":4},{"t":"Pindah ke barbershop lain tanpa berkomentar.","s":3},{"t":"Tetap cukur di sana dengan alasan sudah langganan.","s":2},{"t":"Ikut menyimak dan membenarkan isi ceramahnya.","s":1}], "ex":"Ruang usaha tidak boleh menjadi corong propaganda intoleran; pelanggan berhak menuntut penertiban."},
{"id":"TKP-3338", "q":"Bengkel rekanan dinas dipakai sekelompok orang untuk kumpul rutin membahas paham ekstrem. Anda pegawai yang memakai jasanya. Tindakan Anda?", "opts":[{"t":"Melaporkan temuan itu ke atasan agar kerja sama vendor dievaluasi.","s":5},{"t":"Menegur pemilik bengkel agar tidak memfasilitasi kegiatan itu.","s":4},{"t":"Pindah ke bengkel lain tanpa melapor.","s":3},{"t":"Tetap memakai jasanya karena pelayanannya bagus.","s":2},{"t":"Ikut nimbrung dalam kumpulannya.","s":1}], "ex":"Fasilitas usaha rekanan tidak boleh dipakai untuk paham ekstrem; temuan wajib dilaporkan."},
{"id":"TKP-3339", "q":"Pasar malam di wilayah Anda dijadikan ajang orasi intoleran yang menghasut pengunjung memusuhi kelompok tertentu. Anda aparat kecamatan. Tindakan Anda?", "opts":[{"t":"Membubarkan orasi dan memproses penyelenggaranya sesuai aturan.","s":5},{"t":"Menegur penyelenggara agar menghentikan orasi provokatif.","s":4},{"t":"Membiarkan karena acaranya ramai pengunjung.","s":3},{"t":"Menganggapnya bagian dari kebebasan berpendapat.","s":2},{"t":"Ikut berorasi karena sepaham.","s":1}], "ex":"Ruang publik tidak boleh dipakai untuk hasutan intoleran; aparat wajib menertibkan."},
{"id":"TKP-3340", "q":"Hajatan warga disusupi ceramah provokatif bernada intoleran yang mengajak hadirin memusuhi pemerintah yang sah. Anda tokoh masyarakat yang hadir. Sikap Anda?", "opts":[{"t":"Menghentikan ceramah dan melaporkan penceramahnya ke aparat desa.","s":5},{"t":"Menegur penceramah agar kembali ke acara hajatan.","s":4},{"t":"Pulang lebih awal tanpa berbuat apa-apa.","s":3},{"t":"Diam saja menghormati tuan rumah.","s":2},{"t":"Ikut berteriak mendukung isi ceramahnya.","s":1}], "ex":"Acara warga tidak boleh disusupi hasutan ekstrem; tokoh masyarakat wajib bertindak."},
{"id":"TKP-3341", "q":"Sunatan massal yang disponsori kelompok tertentu ternyata diselingi ceramah doktrin khilafah kepada orang tua peserta. Anda panitia. Tindakan Anda?", "opts":[{"t":"Menghentikan ceramah dan memutus kerja sama dengan sponsor tersebut.","s":5},{"t":"Menegur sponsor agar tidak mencampur bakti sosial dengan doktrin.","s":4},{"t":"Membiarkan karena acaranya gratis untuk warga.","s":3},{"t":"Menganggapnya bonus tausiah biasa.","s":2},{"t":"Ikut menyebarkan doktrinnya ke peserta.","s":1}], "ex":"Bakti sosial tidak boleh ditunggangi doktrin khilafah; panitia wajib menghentikan dan memutus kerja sama."},
{"id":"TKP-3342", "q":"Khotib Jumat di masjid lingkungan Anda menyisipkan hasutan intoleran yang mengkafirkan kelompok berbeda paham. Anda jamaah. Sikap Anda?", "opts":[{"t":"Melaporkan khotib itu ke takmir/DMI/aparat agar dievaluasi.","s":5},{"t":"Menegur takmir masjid agar mengganti khotib.","s":4},{"t":"Pindah shalat ke masjid lain tanpa protes.","s":3},{"t":"Tetap mendengarkan dengan alasan menghormati khotib.","s":2},{"t":"Ikut menyebarkan rekaman khutbahnya.","s":1}], "ex":"Mimbar agama tidak boleh dipakai untuk hasutan intoleran; jamaah wajib melapor lewat jalur yang tepat."},
{"id":"TKP-3343", "q":"Penjaga makam umum menyebarkan paham ekstrem kepada para peziarah sambil menawarkan 'doa khusus perjuangan'. Anda pengunjung. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pengelola makam/aparat setempat.","s":5},{"t":"Menasihati penjaga agar tidak mencampur tugas dengan penyebaran paham.","s":4},{"t":"Mengabaikan dan fokus berziarah.","s":3},{"t":"Mendengarkan dengan alasan menghormati orang tua.","s":2},{"t":"Ikut membeli 'doa khusus' tersebut.","s":1}], "ex":"Fasilitas umum tidak boleh dipakai menyebar paham ekstrem; temuan wajib dilaporkan."},
{"id":"TKP-3344", "q":"Juru parkir liar memalak pengunjung pasar dengan dalih 'infaq jihad' untuk kelompoknya yang berpaham ekstrem. Anda pedagang di sana. Sikap Anda?", "opts":[{"t":"Menolak membayar dan melaporkan pemalakan ke aparat/pengelola pasar.","s":5},{"t":"Menolak membayar dan memperingatkan pedagang lain.","s":4},{"t":"Membayar sedikit agar tidak diganggu.","s":3},{"t":"Membayar dengan alasan keamanan lapak.","s":2},{"t":"Ikut menggalang 'infaq' tersebut.","s":1}], "ex":"Pemalakan berkedok jihad adalah kejahatan; wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3345", "q":"Sebagai penyuluh pertanian, Anda mendapati kelompok tani binaan diajak 'baiat' oleh seseorang yang menyebarkan paham khilafah. Tindakan Anda?", "opts":[{"t":"Mencegah baiat itu dan melaporkan pelaku ke aparat desa/Bhabinkamtibmas.","s":5},{"t":"Memberi penyuluhan tandingan tentang bahaya paham tersebut.","s":4},{"t":"Fokus pada materi pertanian saja.","s":3},{"t":"Membiarkan karena di luar tugas penyuluhan.","s":2},{"t":"Ikut hadir dalam baiatnya.","s":1}], "ex":"Kelompok binaan tidak boleh dibiarkan dibaiat paham khilafah; penyuluh wajib mencegah dan melapor."},
{"id":"TKP-3346", "q":"Sebagai petugas sensus, Anda menemukan satu dusun warganya terpapar paham ekstrem dan menolak didata karena menganggap pemerintah 'thagut'. Sikap Anda?", "opts":[{"t":"Tetap bertugas profesional, mencatat temuan, dan melaporkannya ke koordinator/aparat.","s":5},{"t":"Berkordinasi dengan aparat desa agar pendataan didampingi.","s":4},{"t":"Melewati dusun itu tanpa mendata.","s":3},{"t":"Memaksa dengan cara kasar agar mau didata.","s":2},{"t":"Ikut membenarkan penolakan mereka.","s":1}], "ex":"Penolakan berlabel ekstrem wajib dicatat dan dilaporkan; petugas tetap profesional dan berkoordinasi."},
{"id":"TKP-3347", "q":"Sebagai petugas damkar, Anda dihalangi massa intoleran saat memadamkan kebakaran rumah warga beda keyakinan. Tindakan Anda?", "opts":[{"t":"Tetap memadamkan sambil meminta aparat menertibkan massa penghalang.","s":5},{"t":"Menegur massa agar tidak menghalangi tugas kemanusiaan.","s":4},{"t":"Menunggu massa bubar sendiri.","s":3},{"t":"Membiarkan api membesar agar tidak bentrok.","s":2},{"t":"Ikut membenarkan penghalangan massa.","s":1}], "ex":"Tugas kemanusiaan tidak boleh dihalangi sentimen intoleran; petugas wajib bertindak dan meminta pengamanan."},
{"id":"TKP-3348", "q":"Oknum mengatasnamakan kelompok 'perjuangan' ekstrem meminta 'setoran' ke pedagang pasar dengan dalih jihad. Anda petugas Satpol PP. Tindakan Anda?", "opts":[{"t":"Menindak oknum itu sesuai aturan dan melaporkan jaringannya ke aparat.","s":5},{"t":"Menegur dan membubarkan pungutan liar tersebut.","s":4},{"t":"Membiarkan karena takut berkonflik.","s":3},{"t":"Menganggapnya urusan internal pedagang.","s":2},{"t":"Ikut meminta bagian setoran.","s":1}], "ex":"Pungli berkedok jihad adalah kejahatan; aparat wajib menindak, bukan membiarkan."},
{"id":"TKP-3349", "q":"Sebagai petugas imigrasi di perbatasan, Anda menemukan dokumen palsu milik seseorang yang hendak 'hijrah' ke zona konflik luar negeri untuk bergabung kelompok teroris. Tindakan Anda?", "opts":[{"t":"Menahan yang bersangkutan dan melaporkannya ke atasan/aparat keamanan.","s":5},{"t":"Menolak keberangkatan dan mendalami motifnya sesuai prosedur.","s":4},{"t":"Meloloskan karena dokumennya terlihat meyakinkan.","s":3},{"t":"Membiarkan dengan alasan bukan wewenang.","s":2},{"t":"Membantu memuluskan keberangkatannya.","s":1}], "ex":"Calon kombatan teroris wajib dicegah keberangkatannya dan dilaporkan ke aparat keamanan."},
{"id":"TKP-3350", "q":"Sebagai petugas lapas, Anda menemukan narapidana menyebarkan paham ekstrem ke tahanan lain di bloknya. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pimpinan lapas agar pelaku dipisahkan dan dibina khusus.","s":5},{"t":"Menegur narapidana dan mengawasi blok itu lebih ketat.","s":4},{"t":"Menganggapnya urusan antar-napi.","s":3},{"t":"Membiarkan karena takut dimusuhi napi.","s":2},{"t":"Ikut mendengarkan ceramahnya.","s":1}], "ex":"Penyebaran paham ekstrem di lapas wajib ditindak lewat pemisahan dan pembinaan resmi."}
,
{"id":"TKP-3351", "q":"Pengasuh panti asuhan mengajarkan anak-anak panti paham ekstrem yang mengkafirkan pemerintah. Anda donatur panti itu. Sikap Anda?", "opts":[{"t":"Melaporkan pengasuh itu ke pengelola yayasan dan dinas sosial/aparat.","s":5},{"t":"Menegur pengelola panti agar mengganti pengasuhnya.","s":4},{"t":"Berhenti berdonasi tanpa menjelaskan alasan.","s":3},{"t":"Tetap berdonasi dengan alasan kasihan anak-anak.","s":2},{"t":"Ikut mendukung metode pengasuhannya.","s":1}], "ex":"Anak panti tidak boleh dicekoki paham ekstrem; donatur wajib melapor ke pihak berwenang."},
{"id":"TKP-3352", "q":"Kursus menjahit PKK disusupi instruktur yang menyebarkan paham intoleran kepada ibu-ibu peserta. Anda pengelola kursus. Tindakan Anda?", "opts":[{"t":"Memberhentikan instruktur dan melaporkan penyusupan itu ke pihak berwenang.","s":5},{"t":"Menegur instruktur agar fokus pada materi menjahit.","s":4},{"t":"Membiarkan karena pesertanya betah.","s":3},{"t":"Menganggapnya selingan biasa.","s":2},{"t":"Ikut menyebarkan materi instrukturnya.","s":1}], "ex":"Kegiatan pemberdayaan tidak boleh disusupi paham intoleran; pengelola wajib bertindak tegas."},
{"id":"TKP-3353", "q":"Ketua bank sampah menggalang dana warga yang ternyata disalurkan ke kelompok berpaham ekstrem. Anda nasabah bank sampah. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan penggalangan itu ke aparat desa.","s":5},{"t":"Menasihati ketua agar menghentikan penggalangan.","s":4},{"t":"Berhenti menabung tanpa protes.","s":3},{"t":"Tetap ikut dengan alasan peduli lingkungan.","s":2},{"t":"Ikut menggalang dana tersebut.","s":1}], "ex":"Kegiatan lingkungan tidak boleh ditunggangi pendanaan ekstrem; warga wajib menolak dan melapor."},
{"id":"TKP-3354", "q":"Poskamling di RT Anda dipakai sekelompok orang untuk kajian tertutup berpaham khilafah setiap malam. Anda warga. Tindakan Anda?", "opts":[{"t":"Melaporkan aktivitas itu ke ketua RT/Bhabinkamtibmas.","s":5},{"t":"Menegur pengguna poskamling agar tidak menyalahgunakan fasilitas.","s":4},{"t":"Menghindari poskamling tanpa melapor.","s":3},{"t":"Membiarkan karena mereka juga ikut ronda.","s":2},{"t":"Ikut kajian malamnya.","s":1}], "ex":"Fasilitas keamanan lingkungan tidak boleh dipakai kajian paham khilafah; warga wajib melapor."},
{"id":"TKP-3355", "q":"Kerja bakti warga disusupi orasi intoleran yang menghasut peserta memusuhi kelompok tertentu. Anda peserta. Sikap Anda?", "opts":[{"t":"Menolak orasi itu dan melaporkan penyelundupnya ke ketua RT/lurah.","s":5},{"t":"Menegur orator agar kembali ke agenda kerja bakti.","s":4},{"t":"Pulang lebih awal tanpa berkomentar.","s":3},{"t":"Tetap bekerja sambil mengabaikan orasinya.","s":2},{"t":"Ikut berteriak mendukung orasinya.","s":1}], "ex":"Gotong royong tidak boleh disusupi hasutan intoleran; warga wajib menolak dan melapor."},
{"id":"TKP-3356", "q":"Koperasi simpan pinjam menawarkan pinjaman lunak dengan syarat anggota mengikuti 'pembinaan' berpaham ekstrem. Anda anggota. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan modus itu ke dinas koperasi/aparat.","s":5},{"t":"Menasihati pengurus agar menghentikan syarat tersebut.","s":4},{"t":"Tidak mengajukan pinjaman tanpa protes.","s":3},{"t":"Ikut pembinaan sekadar formalitas demi pinjaman.","s":2},{"t":"Mengikuti pembinaan dan ikut menyebarkannya.","s":1}], "ex":"Layanan keuangan tidak boleh dijadikan alat rekrutmen ekstrem; modusnya wajib dilaporkan."},
{"id":"TKP-3357", "q":"Dana BUMDes dipakai direktur untuk membiayai kegiatan kelompok yang menyebarkan paham khilafah. Anda perangkat desa. Tindakan Anda?", "opts":[{"t":"Melaporkan penyalahgunaan dana itu ke kepala desa/inspektorat/aparat.","s":5},{"t":"Menegur direktur dalam musyawarah desa.","s":4},{"t":"Diam karena takut dimusuhi direktur.","s":3},{"t":"Membiarkan dengan alasan bukan wewenang.","s":2},{"t":"Ikut menikmati dana kegiatan itu.","s":1}], "ex":"Dana desa untuk kelompok khilafah adalah penyelewengan serius; wajib dilaporkan ke aparat."},
{"id":"TKP-3358", "q":"Turnamen voli antar-dusun disusupi panitia yang menyebarkan selebaran intoleran ke penonton. Anda pemain. Sikap Anda?", "opts":[{"t":"Melaporkan panitia ke kepala dusun/aparat agar ditertibkan.","s":5},{"t":"Menegur panitia agar fokus pada pertandingan.","s":4},{"t":"Tetap bermain tanpa memedulikan.","s":3},{"t":"Menganggapnya bagian dari kemeriahan.","s":2},{"t":"Ikut membagikan selebarannya.","s":1}], "ex":"Ajang olahraga tidak boleh disusupi propaganda intoleran; pesertanya wajib melapor."},
{"id":"TKP-3359", "q":"Warkop langganan Anda dipakai sekelompok orang untuk kajian tertutup berpaham ekstrem tiap malam. Anda pelanggan. Sikap Anda?", "opts":[{"t":"Melaporkan aktivitas itu ke aparat/Bhabinkamtibmas.","s":5},{"t":"Meminta pemilik warkop melarang kegiatan tersebut.","s":4},{"t":"Pindah nongkrong tanpa berkomentar.","s":3},{"t":"Tetap nongkrong dengan alasan kopinya enak.","s":2},{"t":"Ikut kajian malamnya.","s":1}], "ex":"Tempat usaha tidak boleh menjadi markas kajian paham ekstrem; warga wajib melapor ke aparat."},
{"id":"TKP-3360", "q":"Pemilik rental PS merekrut anak-anak pelanggan menjadi 'kader' kelompok berpaham ekstrem dengan iming-iming jam main gratis. Anda orang tua pelanggan. Sikap Anda?", "opts":[{"t":"Melarang anak ke sana dan melaporkan pemilik ke aparat.","s":5},{"t":"Menegur pemilik agar berhenti merekrut anak-anak.","s":4},{"t":"Melarang anak tanpa menjelaskan ke pihak lain.","s":3},{"t":"Membiarkan karena anak senang main di sana.","s":2},{"t":"Ikut mendukung karena jam gratisnya menguntungkan.","s":1}], "ex":"Anak-anak tidak boleh direkrut paham ekstrem lewat iming-iming; orang tua wajib melapor ke aparat."},
{"id":"TKP-3361", "q":"Counter pulsa menawarkan pulsa gratis bagi yang mau ikut 'kajian' kelompok intoleran. Anda pelanggan. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan modus itu ke aparat.","s":5},{"t":"Menasihati pemilik counter agar berhenti.","s":4},{"t":"Tidak membeli pulsa di sana lagi.","s":3},{"t":"Ikut kajiannya sekadar demi pulsa gratis.","s":2},{"t":"Ikut kajian dan mengajak teman.","s":1}], "ex":"Iming-iming materi untuk rekrutmen paham intoleran wajib ditolak dan dilaporkan."},
{"id":"TKP-3362", "q":"Agen BRILink di desa Anda ketahuan memfasilitasi transaksi donasi untuk jaringan kelompok ekstrem. Anda nasabah. Tindakan Anda?", "opts":[{"t":"Melaporkan temuan itu ke bank dan aparat penegak hukum.","s":5},{"t":"Menegur agen agar menghentikan transaksi tersebut.","s":4},{"t":"Pindah bertransaksi ke agen lain.","s":3},{"t":"Tetap bertransaksi dengan alasan kebutuhan.","s":2},{"t":"Ikut berdonasi melalui agen itu.","s":1}], "ex":"Fasilitasi dana untuk jaringan ekstrem adalah tindak pidana; wajib dilaporkan ke bank dan aparat."},
{"id":"TKP-3363", "q":"Toko kelontong memasang spanduk intoleran yang menghina kelompok agama tertentu. Anda warga sekitar. Sikap Anda?", "opts":[{"t":"Melaporkan ke ketua RT/aparat agar spanduk diturunkan.","s":5},{"t":"Meminta pemilik toko mencopot spanduknya.","s":4},{"t":"Tidak berbelanja di sana lagi.","s":3},{"t":"Membiarkan dengan alasan hak pemilik toko.","s":2},{"t":"Ikut menyebarkan foto spanduknya.","s":1}], "ex":"Ruang publik tidak boleh dipajang ujaran intoleran; warga wajib menuntut penertiban."},
{"id":"TKP-3364", "q":"Pemilik apotek menolak melayani pembeli beda keyakinan sambil menyebarkan ceramah intoleran. Anda pelanggan yang menyaksikan. Sikap Anda?", "opts":[{"t":"Melaporkan diskriminasi itu ke dinas kesehatan/aparat.","s":5},{"t":"Menegur pemilik agar melayani semua pembeli.","s":4},{"t":"Pindah ke apotek lain.","s":3},{"t":"Tetap membeli karena butuh obat.","s":2},{"t":"Ikut membenarkan penolakannya.","s":1}], "ex":"Diskriminasi layanan berdasar keyakinan melanggar hukum; wajib dilaporkan."},
{"id":"TKP-3365", "q":"Bidan desa menolak menolong persalinan warga beda keyakinan dengan dalih paham intoleran yang dianutnya. Anda keluarga pasien. Tindakan Anda?", "opts":[{"t":"Melaporkan ke dinas kesehatan agar bidan itu ditindak dan pasien tertangani.","s":5},{"t":"Menuntut bidan segera menolong karena itu kewajibannya.","s":4},{"t":"Mencari bidan lain tanpa melapor.","s":3},{"t":"Memaklumi keyakinan bidan itu.","s":2},{"t":"Ikut membenarkan penolakannya.","s":1}], "ex":"Tenaga kesehatan wajib menolong tanpa diskriminasi keyakinan; penolakan wajib dilaporkan."},
{"id":"TKP-3366", "q":"Tukang pijat langganan menawarkan 'terapi ruqyah perjuangan' yang diselingi doktrin ekstrem anti-pemerintah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan praktik itu ke aparat setempat.","s":5},{"t":"Menasihati agar tidak mencampur usaha dengan doktrin.","s":4},{"t":"Tidak memakai jasanya lagi.","s":3},{"t":"Tetap pijat dengan alasan sudah cocok.","s":2},{"t":"Ikut menyebarkan 'terapi' tersebut.","s":1}], "ex":"Jasa apapun tidak boleh menjadi kedok penyebaran doktrin ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3367", "q":"Tukang las yang mengerjakan proyek kantor menawarkan pekerjaan ke pemuda desa dengan syarat mengikuti 'pembinaan' paham khilafah. Anda pengawas proyek. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pimpinan proyek dan aparat agar ditindak.","s":5},{"t":"Menegur tukang las agar berhenti merekrut.","s":4},{"t":"Mengabaikan karena di luar lingkup proyek.","s":3},{"t":"Membiarkan dengan alasan membantu pemuda dapat kerja.","s":2},{"t":"Ikut merekomendasikan pemuda untuk ikut.","s":1}], "ex":"Lowongan kerja tidak boleh dijadikan umpan rekrutmen paham khilafah; wajib dilaporkan."},
{"id":"TKP-3368", "q":"Mandor proyek kantor merekrut kuli bangunan menjadi anggota kelompok berpaham ekstrem dengan iming-iming upah lebih. Anda pelaksana proyek. Sikap Anda?", "opts":[{"t":"Melaporkan mandor itu ke pimpinan proyek dan aparat.","s":5},{"t":"Menegur mandor agar berhenti merekrut pekerja.","s":4},{"t":"Fokus pada pekerjaan tanpa mencampuri.","s":3},{"t":"Membiarkan dengan alasan urusan mandor.","s":2},{"t":"Ikut diajak karena iming-imingnya.","s":1}], "ex":"Pekerja tidak boleh direkrut paham ekstrem di lokasi proyek negara; wajib dilaporkan."},
{"id":"TKP-3369", "q":"Sopir taksi online yang Anda tumpangi memutar ceramah kelompok teroris yang mengagungkan aksi terorisme. Sikap Anda sebagai penumpang?", "opts":[{"t":"Meminta dimatikan dan melaporkan ke platform/aparat bila ia menolak.","s":5},{"t":"Menegur sopir agar mengganti tontonan.","s":4},{"t":"Diam dan memakai earphone.","s":3},{"t":"Membiarkan karena menghormati sopir.","s":2},{"t":"Ikut menyimak dengan antusias.","s":1}], "ex":"Propaganda terorisme di ruang publik wajib ditolak; penumpang berhak menuntut dan melapor."},
{"id":"TKP-3370", "q":"Pramubakti honorer di unit Anda diajak iuran 'perjuangan' oleh senior untuk kelompok yang menyebarkan paham khilafah. Anda rekan seunit. Sikap Anda?", "opts":[{"t":"Menasihati agar menolak dan melaporkan ajakan itu ke pimpinan.","s":5},{"t":"Memperingatkan tentang bahaya kelompok tersebut.","s":4},{"t":"Menganggapnya urusan pribadi masing-masing.","s":3},{"t":"Ikut iuran agar tidak dikucilkan.","s":2},{"t":"Ikut menggalang iuran tersebut.","s":1}], "ex":"Iuran untuk kelompok khilafah adalah pendanaan ekstremisme; wajib ditolak dan dilaporkan."},
{"id":"TKP-3371", "q":"Senior mengajak Anda PPPK baru untuk 'solidaritas' mendukung kelompok pegawai yang menyebarkan paham intoleran di kantor. Sikap Anda?", "opts":[{"t":"Menolak tegas dan melaporkan kelompok itu ke pimpinan/BKPSDM.","s":5},{"t":"Menolak ajakan dan menjaga jarak dari kelompok tersebut.","s":4},{"t":"Netral tanpa memihak siapa pun.","s":3},{"t":"Ikut agar diterima di lingkungan baru.","s":2},{"t":"Aktif bergabung dalam kelompok itu.","s":1}], "ex":"Solidaritas tidak boleh dipakai untuk paham intoleran; PPPK wajib menolak dan melapor."},
{"id":"TKP-3372", "q":"Sebagai auditor, Anda menemukan aliran dana instansi ke kelompok yang menyebarkan paham ekstrem, lalu atasan menekan agar temuan ditutup. Sikap Anda?", "opts":[{"t":"Tetap melaporkan temuan sesuai prosedur ke inspektorat/aparat penegak hukum.","s":5},{"t":"Mencatat temuan resmi dan menolak menutupinya.","s":4},{"t":"Mengikuti perintah atasan menutup temuan.","s":3},{"t":"Menghapus temuan dari laporan.","s":2},{"t":"Ikut menikmati aliran dana itu.","s":1}], "ex":"Auditor wajib independen; temuan dana ke kelompok ekstrem tidak boleh ditutup atas tekanan siapa pun."},
{"id":"TKP-3373", "q":"Sebagai penyuluh KB, Anda mendapati kelompok ibu-ibu binaan diajak 'kajian' yang isinya doktrin intoleran anti-pemerintah. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pimpinan dan aparat agar kegiatan itu dihentikan.","s":5},{"t":"Memberi penyuluhan tandingan tentang bahaya paham tersebut.","s":4},{"t":"Fokus pada materi KB saja.","s":3},{"t":"Membiarkan karena di luar tugas.","s":2},{"t":"Ikut menghadiri kajiannya.","s":1}], "ex":"Kelompok binaan tidak boleh menjadi sasaran doktrin intoleran; penyuluh wajib melapor."},
{"id":"TKP-3374", "q":"Warga melapor kepada Anda sebagai Babinsa bahwa ada perekrutan paham radikal di dusun binaannya. Tindakan Anda?", "opts":[{"t":"Menindaklanjuti laporan dengan pemetaan dan koordinasi ke aparat kepolisian/BNPT.","s":5},{"t":"Mendatangi lokasi untuk verifikasi dan pembinaan awal.","s":4},{"t":"Mencatat saja tanpa tindak lanjut.","s":3},{"t":"Menganggapnya isu biasa.","s":2},{"t":"Membocorkan identitas pelapor ke pihak yang dilaporkan.","s":1}], "ex":"Laporan perekrutan paham radikal wajib ditindaklanjuti aparat teritorial lewat koordinasi resmi."},
{"id":"TKP-3375", "q":"Sekdes mengajak perangkat desa menandatangani dukungan untuk organisasi yang dibubarkan pemerintah karena paham ekstremnya. Anda perangkat desa. Sikap Anda?", "opts":[{"t":"Menolak menandatangani dan melaporkan ajakan itu ke camat/aparat.","s":5},{"t":"Menolak dan menasihati sekdes agar tidak mengulanginya.","s":4},{"t":"Menolak diam-diam tanpa melapor.","s":3},{"t":"Menandatangani agar tidak dimusuhi.","s":2},{"t":"Ikut mengajak perangkat lain menandatangani.","s":1}], "ex":"Aparatur desa tidak boleh mendukung organisasi terlarang; ajakan wajib ditolak dan dilaporkan."}
,
{"id":"TKP-3376", "q":"Sebagai kaur, Anda diminta membubuhkan stempel desa pada surat kegiatan kelompok yang diketahui menyebarkan paham khilafah. Sikap Anda?", "opts":[{"t":"Menolak membubuhkan stempel dan melaporkan permintaan itu ke kepala desa/camat.","s":5},{"t":"Menolak dengan alasan kegiatan tidak sesuai ketentuan.","s":4},{"t":"Menunda-nunda tanpa keputusan jelas.","s":3},{"t":"Membubuhkan stempel agar tidak dipersulit.","s":2},{"t":"Membubuhkan dan ikut mempromosikan kegiatan itu.","s":1}], "ex":"Stempel resmi tidak boleh dipakai melegalkan kegiatan paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3377", "q":"Warga melapor kepada Anda sebagai kadus bahwa ada rumah yang dijadikan tempat doktrin paham ekstrem tiap malam. Tindakan Anda?", "opts":[{"t":"Meneruskan laporan ke kepala desa dan Bhabinkamtibmas untuk ditindaklanjuti.","s":5},{"t":"Mendatangi lokasi bersama ketua RT untuk verifikasi.","s":4},{"t":"Mencatat laporan tanpa tindak lanjut.","s":3},{"t":"Menganggapnya gosip warga.","s":2},{"t":"Memberi tahu pemilik rumah bahwa ia dilaporkan.","s":1}], "ex":"Laporan warga soal doktrin ekstrem wajib diteruskan ke aparat; identitas pelapor wajib dilindungi."},
{"id":"TKP-3378", "q":"Hansip diajak menjaga acara tabligh akbar yang ternyata orasi kelompok intoleran yang provokatif. Anda komandan hansip. Sikap Anda?", "opts":[{"t":"Menolak pengerahan dan melaporkan acara itu ke lurah/aparat.","s":5},{"t":"Menarik anggota hansip dari acara tersebut.","s":4},{"t":"Tetap menjaga dengan alasan tugas.","s":3},{"t":"Membiarkan anggota ikut mendengarkan orasi.","s":2},{"t":"Ikut mengamankan sambil mendukung orasinya.","s":1}], "ex":"Aparat keamanan lingkungan tidak boleh mengamankan orasi intoleran; wajib menolak dan melapor."},
{"id":"TKP-3379", "q":"Takmir masjid ditawari penceramah bayaran tinggi dengan syarat menyampaikan ceramah bernada intoleran. Anda pengurus takmir. Sikap Anda?", "opts":[{"t":"Menolak tawaran dan melaporkan penceramah itu ke DMI/aparat.","s":5},{"t":"Menolak dan memilih penceramah yang jelas moderat.","s":4},{"t":"Menerima dengan alasan kas masjid bertambah.","s":3},{"t":"Membiarkan karena jamaah terlihat antusias.","s":2},{"t":"Ikut mempromosikan ceramahnya.","s":1}], "ex":"Mimbar masjid tidak boleh dibeli untuk ceramah intoleran; tawaran wajib ditolak dan dilaporkan."},
{"id":"TKP-3380", "q":"Pengurus rumah ibadah minoritas ditawari 'perlindungan' oleh kelompok intoleran dengan imbalan uang keamanan bulanan. Anda pengurus. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan pemerasan itu ke aparat penegak hukum.","s":5},{"t":"Menolak dan berkoordinasi dengan aparat untuk pengamanan resmi.","s":4},{"t":"Membayar sedikit agar ibadah tenang.","s":3},{"t":"Membayar rutin demi keamanan.","s":2},{"t":"Ikut bergabung dengan kelompok itu.","s":1}], "ex":"Pemerasan berkedok perlindungan terhadap rumah ibadah wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3381", "q":"Tokoh adat diminta memberikan legitimasi adat untuk kegiatan kelompok yang menyebarkan paham khilafah. Anda tokoh adat itu. Sikap Anda?", "opts":[{"t":"Menolak tegas dan melaporkan permintaan itu ke aparat desa.","s":5},{"t":"Menolak dengan alasan adat tidak mencampuri paham tersebut.","s":4},{"t":"Memberi legitimasi agar tidak dimusuhi.","s":3},{"t":"Diam saja tanpa pendirian.","s":2},{"t":"Memberi legitimasi dan ikut menghadiri.","s":1}], "ex":"Legitimasi adat tidak boleh dipakai untuk paham khilafah; tokoh adat wajib menolak dan melapor."},
{"id":"TKP-3382", "q":"Tokoh pemuda diajak menjadi koordinator lapangan kelompok berpaham ekstrem dengan iming-iming jabatan. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan itu ke aparat.","s":5},{"t":"Menolak dan memperingatkan pemuda lain agar tidak terjebak.","s":4},{"t":"Menolak halus tanpa melapor.","s":3},{"t":"Menerima karena iming-iming jabatannya.","s":2},{"t":"Aktif mengkoordinir untuk kelompok itu.","s":1}], "ex":"Tokoh pemuda tidak boleh menjadi koordinator paham ekstrem; ajakan wajib ditolak dan dilaporkan."},
{"id":"TKP-3383", "q":"Sekretariat karang taruna dipakai sekelompok orang untuk kajian paham khilafah tanpa sepengetahuan pengurus. Anda ketua karang taruna. Tindakan Anda?", "opts":[{"t":"Menghentikan kegiatan dan melaporkan ke aparat desa.","s":5},{"t":"Menegur pengguna dan mengunci sekretariat dari pihak luar.","s":4},{"t":"Membiarkan karena mereka juga pemuda desa.","s":3},{"t":"Menganggapnya kegiatan positif.","s":2},{"t":"Ikut bergabung dalam kajiannya.","s":1}], "ex":"Fasilitas pemuda tidak boleh dipakai kajian paham khilafah; pengurus wajib menertibkan dan melapor."},
{"id":"TKP-3384", "q":"Arisan PKK disusupi penggalangan dana untuk kelompok yang menyebarkan paham intoleran. Anda bendahara arisan. Sikap Anda?", "opts":[{"t":"Menolak penggalangan dan melaporkan ke ketua PKK/aparat.","s":5},{"t":"Menegur penggagas agar menghentikan penggalangan.","s":4},{"t":"Tidak ikut iuran tanpa protes.","s":3},{"t":"Ikut iuran agar tidak dikucilkan.","s":2},{"t":"Ikut menggalang dana tersebut.","s":1}], "ex":"Arisan warga tidak boleh ditunggangi dana paham intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3385", "q":"Kegiatan balita di posyandu disusupi pembagian buku cerita anak bermuatan intoleran. Anda kader posyandu. Tindakan Anda?", "opts":[{"t":"Menarik buku itu dan melaporkan ke puskesmas/aparat.","s":5},{"t":"Menegur penyebar agar tidak mengulangi.","s":4},{"t":"Membiarkan karena bukunya gratis.","s":3},{"t":"Menganggapnya buku cerita biasa.","s":2},{"t":"Ikut membagikannya ke orang tua.","s":1}], "ex":"Anak-anak tidak boleh dicekoki bacaan intoleran; temuan wajib dilaporkan."},
{"id":"TKP-3386", "q":"Kader posyandu diminta menyerahkan data warga binaan untuk 'pendataan dakwah' kelompok berpaham ekstrem. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan permintaan data itu ke puskesmas/aparat.","s":5},{"t":"Menolak dengan alasan data warga dilindungi.","s":4},{"t":"Memberi sebagian data agar tidak dimusuhi.","s":3},{"t":"Menyerahkan data karena diminta baik-baik.","s":2},{"t":"Aktif membantu pendataan itu.","s":1}], "ex":"Data warga tidak boleh diserahkan untuk rekrutmen paham ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3387", "q":"Guru PAUD mengajarkan anak didiknya lagu bernada intoleran yang mengkafirkan kelompok berbeda keyakinan. Anda orang tua murid. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola PAUD dan dinas pendidikan agar dievaluasi.","s":5},{"t":"Menegur guru agar menghentikan lagu itu.","s":4},{"t":"Memindahkan anak tanpa protes.","s":3},{"t":"Membiarkan karena anak masih kecil.","s":2},{"t":"Ikut mengajarkan lagu itu di rumah.","s":1}], "ex":"Anak usia dini tidak boleh diajari ujaran intoleran; orang tua wajib melapor ke pihak berwenang."},
{"id":"TKP-3388", "q":"Ustadz kampung ditawari amplop besar agar ceramahnya menyisipkan hasutan intoleran. Anda jamaah yang mengetahui. Sikap Anda?", "opts":[{"t":"Melaporkan tawaran itu ke tokoh masyarakat/aparat.","s":5},{"t":"Menasihati ustadz agar menolak tawaran tersebut.","s":4},{"t":"Diam saja bukan urusan Anda.","s":3},{"t":"Tetap mendengarkan ceramahnya.","s":2},{"t":"Ikut menyebarkan hasutannya.","s":1}], "ex":"Ceramah agama tidak boleh dibeli untuk hasutan intoleran; warga wajib melapor."},
{"id":"TKP-3389", "q":"Pesantren di wilayah Anda disusupi ustadz baru yang mengajarkan paham khilafah kepada santri. Anda tokoh masyarakat. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pengasuh pesantren dan aparat agar ditindaklanjuti.","s":5},{"t":"Meminta pengasuh mengevaluasi ustadz tersebut.","s":4},{"t":"Membiarkan karena urusan internal pesantren.","s":3},{"t":"Menganggapnya perbedaan mazhab biasa.","s":2},{"t":"Ikut mendukung ustadz baru itu.","s":1}], "ex":"Pesantren tidak boleh disusupi paham khilafah; temuan wajib dilaporkan ke pengasuh dan aparat."},
{"id":"TKP-3390", "q":"Rumah ibadah minoritas didemo kelompok intoleran yang menuntut pembubaran kegiatan ibadah. Anda aparat kecamatan. Tindakan Anda?", "opts":[{"t":"Mengamankan rumah ibadah dan memproses pendemo sesuai hukum.","s":5},{"t":"Memediasi dengan menegaskan hak beribadah dilindungi undang-undang.","s":4},{"t":"Meminta ibadah dihentikan sementara agar aman.","s":3},{"t":"Membiarkan demo karena massa banyak.","s":2},{"t":"Ikut menuntut pembubaran.","s":1}], "ex":"Kebebasan beribadah dilindungi konstitusi; aparat wajib melindungi, bukan tunduk pada pendemo intoleran."},
{"id":"TKP-3391", "q":"Pengurus panti jompo membiarkan penceramah menyebarkan paham ekstrem kepada para lansia penghuni panti. Anda keluarga salah satu penghuni. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola yayasan dan dinas sosial.","s":5},{"t":"Menegur pengurus agar mengganti penceramah.","s":4},{"t":"Memindahkan keluarga ke panti lain.","s":3},{"t":"Membiarkan karena penghuninya sudah sepuh.","s":2},{"t":"Ikut mendukung penceramahnya.","s":1}], "ex":"Lansia tidak boleh menjadi sasaran doktrin ekstrem; keluarga wajib melapor ke pihak berwenang."},
{"id":"TKP-3392", "q":"DKM masjid ditekan sekelompok orang agar menyerahkan jadwal khutbah untuk diisi penceramah intoleran. Anda pengurus DKM. Sikap Anda?", "opts":[{"t":"Menolak tekanan dan melaporkan ke DMI/aparat.","s":5},{"t":"Menolak dengan alasan khotib sudah terjadwal resmi.","s":4},{"t":"Menyerahkan satu jadwal agar tidak ribut.","s":3},{"t":"Menyerahkan karena takut.","s":2},{"t":"Ikut mengundang penceramah itu.","s":1}], "ex":"Jadwal khutbah tidak boleh direbut untuk penceramah intoleran; tekanan wajib ditolak dan dilaporkan."},
{"id":"TKP-3393", "q":"Marbot masjid diminta menyerahkan kunci masjid untuk kajian tertutup berpaham khilafah tiap malam. Sikap Anda sebagai marbot?", "opts":[{"t":"Menolak dan melaporkan permintaan itu ke takmir/aparat.","s":5},{"t":"Menolak dengan alasan masjid untuk ibadah umum.","s":4},{"t":"Memberi kunci agar tidak dimusuhi.","s":3},{"t":"Memberi kunci karena dibayar.","s":2},{"t":"Ikut menjaga kajian itu.","s":1}], "ex":"Masjid tidak boleh dipakai kajian tertutup paham khilafah; marbot wajib menolak dan melapor."},
{"id":"TKP-3394", "q":"Imam masjid ditekan jamaahnya agar khutbahnya berisi hasutan intoleran. Anda imam itu. Sikap Anda?", "opts":[{"t":"Menolak tekanan dan melaporkan ke takmir/DMI/aparat.","s":5},{"t":"Tetap berkhutbah dengan materi yang damai dan moderat.","s":4},{"t":"Menuruti sebagian agar jamaah tidak pergi.","s":3},{"t":"Menuruti karena takut kehilangan jamaah.","s":2},{"t":"Menuruti dan ikut menghasut.","s":1}], "ex":"Imam tidak boleh tunduk pada tekanan hasutan intoleran; wajib menolak dan melapor."},
{"id":"TKP-3395", "q":"Tamu yang menginap di rumah warga melebihi 1x24 jam ternyata menyebarkan paham ekstrem ke tetangga. Anda ketua RT. Tindakan Anda?", "opts":[{"t":"Melaporkan ke Bhabinkamtibmas untuk didata dan ditindaklanjuti.","s":5},{"t":"Mendatangi tuan rumah dan meminta tamunya didata resmi.","s":4},{"t":"Membiarkan karena tamu akan segera pergi.","s":3},{"t":"Menganggapnya urusan tuan rumah.","s":2},{"t":"Ikut mendengarkan ceramah tamu itu.","s":1}], "ex":"Tamu yang menyebar paham ekstrem wajib didata dan dilaporkan; ketua RT bertanggung jawab atas lingkungannya."},
{"id":"TKP-3396", "q":"Portal RW ditutup sekelompok warga untuk 'sweeping' intoleran dan mengusir warga beda keyakinan. Anda ketua RW. Tindakan Anda?", "opts":[{"t":"Membuka portal dan melaporkan aksi sweeping ke aparat.","s":5},{"t":"Menegur pelaku agar menghentikan sweeping.","s":4},{"t":"Membiarkan karena tidak mau berkonflik.","s":3},{"t":"Mendukung karena alasan keamanan.","s":2},{"t":"Ikut memimpin sweeping.","s":1}], "ex":"Sweeping berdasar keyakinan adalah tindakan intoleran yang melanggar hukum; wajib dihentikan dan dilaporkan."},
{"id":"TKP-3397", "q":"Sebagai petugas pajak, Anda mendapati wajib pajak sebuah yayasan yang dananya mengalir ke kelompok berpaham ekstrem. Tindakan Anda?", "opts":[{"t":"Melaporkan temuan ke atasan dan PPATK/aparat penegak hukum.","s":5},{"t":"Mendalami aliran dana sesuai prosedur audit.","s":4},{"t":"Mengabaikan karena di luar urusan pajak.","s":3},{"t":"Menutup temuan karena yayasannya berpengaruh.","s":2},{"t":"Ikut menerima 'jatah' dari yayasan.","s":1}], "ex":"Aliran dana ke kelompok ekstrem wajib dilaporkan ke PPATK dan aparat; petugas tidak boleh menutup temuan."},
{"id":"TKP-3398", "q":"Ambulans desa diminta mengangkut massa aksi kelompok intoleran, bukan pasien. Anda sopir ambulans. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan penyalahgunaan itu ke kepala desa/dinas kesehatan.","s":5},{"t":"Menolak dengan alasan ambulans hanya untuk pasien.","s":4},{"t":"Mengangkut dengan alasan kemanusiaan.","s":3},{"t":"Mengangkut karena diperintah tokoh.","s":2},{"t":"Ikut beraksi bersama massa.","s":1}], "ex":"Ambulans adalah fasilitas kesehatan, tidak boleh dipakai untuk aksi massa intoleran."},
{"id":"TKP-3399", "q":"Terminal bus dipakai sekelompok orang untuk berorasi intoleran dan menghasut penumpang. Anda petugas Dishub. Tindakan Anda?", "opts":[{"t":"Membubarkan orasi dan berkoordinasi dengan aparat keamanan.","s":5},{"t":"Menegur orator agar menghentikan hasutannya.","s":4},{"t":"Membiarkan karena terminal tempat umum.","s":3},{"t":"Menganggapnya kebebasan berpendapat.","s":2},{"t":"Ikut mendengarkan orasinya.","s":1}], "ex":"Fasilitas publik tidak boleh dipakai untuk hasutan intoleran; petugas wajib menertibkan."},
{"id":"TKP-3400", "q":"Di bandara, Anda petugas melihat seseorang menyebarkan selebaran paham khilafah kepada calon penumpang. Tindakan Anda?", "opts":[{"t":"Mengamankan pelaku dan melaporkannya ke otoritas bandara/kepolisian.","s":5},{"t":"Menegur dan meminta selebarannya dimusnahkan.","s":4},{"t":"Membiarkan karena sibuk bertugas.","s":3},{"t":"Menganggapnya bukan wewenang.","s":2},{"t":"Ikut mengambil selebarannya.","s":1}], "ex":"Bandara adalah objek vital; penyebaran paham khilafah di sana wajib ditindak aparat."}
,
{"id":"TKP-3401", "q":"ABK kapal penyeberangan menyebarkan paham ekstrem kepada penumpang selama pelayaran. Anda penumpang. Sikap Anda?", "opts":[{"t":"Melaporkan ke nakhoda/petugas keamanan kapal setiba di pelabuhan.","s":5},{"t":"Menegur ABK agar berhenti menyebarkan paham itu.","s":4},{"t":"Pindah tempat duduk menjauhi.","s":3},{"t":"Mendengarkan dengan alasan menghormati.","s":2},{"t":"Ikut berdiskusi dan membenarkan.","s":1}], "ex":"Angkutan umum tidak boleh menjadi sarana penyebaran paham ekstrem; penumpang wajib melapor."},
{"id":"TKP-3402", "q":"Pedagang asongan di stasiun menjajakan dagangan sambil menyebarkan selebaran propaganda khilafah. Anda petugas stasiun. Tindakan Anda?", "opts":[{"t":"Menertibkan pedagang dan menyita selebarannya untuk dilaporkan.","s":5},{"t":"Menegur agar berhenti menyebarkan selebaran.","s":4},{"t":"Membiarkan karena kasihan padanya.","s":3},{"t":"Menganggapnya bukan wewenang.","s":2},{"t":"Ikut mengambil selebarannya.","s":1}], "ex":"Fasilitas publik wajib steril dari propaganda khilafah; petugas wajib menertibkan."},
{"id":"TKP-3403", "q":"Di pos perbatasan darat, pelintas batas menawarkan buku-buku berpaham ekstrem kepada warga sekitar. Anda petugas. Tindakan Anda?", "opts":[{"t":"Menyita buku-buku itu dan melaporkan ke atasan/aparat keamanan.","s":5},{"t":"Menegur dan melarang penyebaran di wilayah perbatasan.","s":4},{"t":"Membiarkan karena sudah lewat pos.","s":3},{"t":"Menganggapnya urusan pribadi.","s":2},{"t":"Ikut menerima bukunya.","s":1}], "ex":"Wilayah perbatasan rawan infiltrasi paham ekstrem; petugas wajib menyita dan melapor."},
{"id":"TKP-3404", "q":"Pembina panti rehabilitasi narkoba menyisipkan doktrin ekstrem yang menghasut pecandu memusuhi pemerintah. Anda pekerja sosial. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola panti dan dinas sosial/aparat.","s":5},{"t":"Menegur pembina agar fokus pada rehabilitasi.","s":4},{"t":"Diam karena bukan bidang Anda.","s":3},{"t":"Membiarkan dengan alasan metode terapi.","s":2},{"t":"Ikut mendukung metodenya.","s":1}], "ex":"Kelompok rentan di panti rehab tidak boleh dicekoki doktrin ekstrem; wajib dilaporkan."},
{"id":"TKP-3405", "q":"Guru SLB mengajarkan murid berkebutuhan khusus ujaran intoleran yang menghina kelompok lain. Anda orang tua murid. Sikap Anda?", "opts":[{"t":"Melaporkan ke kepala sekolah dan dinas pendidikan.","s":5},{"t":"Menegur guru agar menghentikan ajarannya.","s":4},{"t":"Memindahkan anak tanpa protes.","s":3},{"t":"Membiarkan karena anak tidak paham.","s":2},{"t":"Ikut membenarkan ajarannya.","s":1}], "ex":"Anak berkebutuhan khusus wajib dilindungi dari ujaran intoleran; orang tua wajib melapor."},
{"id":"TKP-3406", "q":"Kursus komputer gratis untuk pemuda ternyata diselingi materi doktrin khilafah oleh instrukturnya. Anda peserta. Sikap Anda?", "opts":[{"t":"Melaporkan ke penyelenggara kursus dan aparat.","s":5},{"t":"Menegur instruktur agar fokus pada materi komputer.","s":4},{"t":"Tetap ikut demi ilmunya.","s":3},{"t":"Menganggapnya bonus wawasan.","s":2},{"t":"Ikut menyebarkan materinya.","s":1}], "ex":"Pelatihan gratis tidak boleh ditunggangi doktrin khilafah; peserta wajib melapor."},
{"id":"TKP-3407", "q":"Koperasi tani diminta menyisihkan hasil panen untuk 'dana perjuangan' kelompok berpaham ekstrem. Anda anggota. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pengurus/aparat desa.","s":5},{"t":"Menasihati pengurus agar menolak permintaan itu.","s":4},{"t":"Tidak ikut menyisihkan tanpa protes.","s":3},{"t":"Ikut menyisihkan agar tidak dikucilkan.","s":2},{"t":"Aktif menggalang dana itu.","s":1}], "ex":"Hasil panen petani tidak boleh dipalak untuk paham ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3408", "q":"Gardu ronda diminta sumbangan rutin untuk 'keamanan' oleh kelompok yang menyebarkan paham intoleran. Anda warga. Sikap Anda?", "opts":[{"t":"Menolak membayar dan melaporkan ke ketua RT/aparat.","s":5},{"t":"Menolak dan mengajak warga lain menolak.","s":4},{"t":"Membayar sedikit agar aman.","s":3},{"t":"Membayar rutin demi ketenangan.","s":2},{"t":"Ikut mengutip sumbangan itu.","s":1}], "ex":"Pungutan berkedok keamanan oleh kelompok intoleran wajib ditolak dan dilaporkan."},
{"id":"TKP-3409", "q":"Gapura RT dipasangi spanduk provokatif bernada intoleran oleh sekelompok warga. Anda ketua RT. Tindakan Anda?", "opts":[{"t":"Mencopot spanduk dan melaporkan pelakunya ke lurah/aparat.","s":5},{"t":"Memerintahkan pencopotan spanduk itu segera.","s":4},{"t":"Membiarkan karena takut berkonflik.","s":3},{"t":"Menganggapnya aspirasi warga.","s":2},{"t":"Ikut memasang spanduk serupa.","s":1}], "ex":"Fasilitas umum tidak boleh dipasangi ujaran intoleran; ketua RT wajib menertibkan."},
{"id":"TKP-3410", "q":"Arisan bapak-bapak disusupi ceramah hasutan ekstrem yang menghasut peserta memusuhi pemerintah yang sah. Anda anggota arisan. Sikap Anda?", "opts":[{"t":"Menolak ceramah itu dan melaporkan penceramahnya ke aparat.","s":5},{"t":"Menegur agar arisan kembali ke agenda semula.","s":4},{"t":"Tidak hadir lagi tanpa penjelasan.","s":3},{"t":"Tetap hadir demi silaturahmi.","s":2},{"t":"Ikut menyebarkan ceramahnya.","s":1}], "ex":"Perkumpulan warga tidak boleh disusupi hasutan ekstrem; anggota wajib menolak dan melapor."},
{"id":"TKP-3411", "q":"Rentenir berkedok 'koperasi syariah perjuangan' menawarkan pinjaman dan merekrut nasabahnya ke paham khilafah. Anda nasabah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan modus itu ke aparat/OJK.","s":5},{"t":"Menasihati tetangga agar tidak terjebak.","s":4},{"t":"Tidak meminjam lagi tanpa melapor.","s":3},{"t":"Tetap meminjam karena bunganya ringan.","s":2},{"t":"Ikut merekrut nasabah baru.","s":1}], "ex":"Jasa keuangan tidak boleh menjadi kedok rekrutmen paham khilafah; wajib dilaporkan."},
{"id":"TKP-3412", "q":"Pasar desa dipakai sekelompok orang untuk berorasi intoleran setiap hari pasar. Anda pedagang. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola pasar dan aparat agar ditertibkan.","s":5},{"t":"Meminta pengelola melarang orasi di area pasar.","s":4},{"t":"Fokus berdagang tanpa memedulikan.","s":3},{"t":"Mendengarkan karena ramai.","s":2},{"t":"Ikut berteriak mendukung.","s":1}], "ex":"Pasar sebagai ruang publik wajib steril dari orasi intoleran; pedagang wajib melapor."},
{"id":"TKP-3413", "q":"Lapangan futsal disewa rutin oleh kelompok yang menjadikannya ajang rekrutmen paham ekstrem. Anda pengelola lapangan. Tindakan Anda?", "opts":[{"t":"Membatalkan sewa dan melaporkan kelompok itu ke aparat.","s":5},{"t":"Menegur penyewa agar menghentikan rekrutmen.","s":4},{"t":"Tetap menyewakan karena bayarannya lancar.","s":3},{"t":"Menganggapnya urusan penyewa.","s":2},{"t":"Ikut bergabung dalam kegiatannya.","s":1}], "ex":"Fasilitas olahraga tidak boleh disewa untuk rekrutmen paham ekstrem; pengelola wajib bertindak."},
{"id":"TKP-3414", "q":"Angkringan langganan Anda dipakai kajian tertutup berpaham ekstrem dan pemiliknya ikut menyebarkan. Sikap Anda sebagai pelanggan?", "opts":[{"t":"Melaporkan ke Bhabinkamtibmas/aparat setempat.","s":5},{"t":"Menasihati pemilik agar menghentikan kegiatan itu.","s":4},{"t":"Pindah jajan tanpa berkomentar.","s":3},{"t":"Tetap jajan karena makanannya enak.","s":2},{"t":"Ikut kajian malamnya.","s":1}], "ex":"Tempat usaha tidak boleh menjadi markas paham ekstrem; warga wajib melapor ke aparat."},
{"id":"TKP-3415", "q":"Warnet dekat sekolah dipakai sekelompok orang untuk menyebarkan propaganda teroris ke anak-anak. Anda orang tua murid. Sikap Anda?", "opts":[{"t":"Melaporkan ke pemilik warnet, sekolah, dan aparat.","s":5},{"t":"Menegur pemilik agar mengawasi penggunanya.","s":4},{"t":"Melarang anak ke warnet itu.","s":3},{"t":"Membiarkan karena bukan urusan.","s":2},{"t":"Menganggapnya sekadar main internet.","s":1}], "ex":"Anak-anak wajib dilindungi dari propaganda teroris; temuan wajib dilaporkan ke aparat."},
{"id":"TKP-3416", "q":"Toko ATK langganan kantor menyelipkan stiker propaganda khilafah di setiap paket belanja dinas. Anda bagian pengadaan. Tindakan Anda?", "opts":[{"t":"Melaporkan ke atasan agar vendor dievaluasi dan stiker dimusnahkan.","s":5},{"t":"Menegur pemilik toko agar berhenti.","s":4},{"t":"Membuang stikernya diam-diam.","s":3},{"t":"Mengabaikan karena hanya stiker.","s":2},{"t":"Ikut menempel stikernya.","s":1}], "ex":"Belanja dinas tidak boleh disusupi propaganda khilafah; temuan wajib dilaporkan."},
{"id":"TKP-3417", "q":"Agen travel menawarkan paket wisata religi murah yang ternyata diisi doktrin ekstrem anti-pemerintah. Anda calon peserta. Sikap Anda?", "opts":[{"t":"Membatalkan dan melaporkan biro itu ke aparat.","s":5},{"t":"Meminta itinerary diganti yang normal.","s":4},{"t":"Tetap ikut demi wisatanya.","s":3},{"t":"Ikut doktrinnya sekadar formalitas.","s":2},{"t":"Mengikuti dan menyebarkannya.","s":1}], "ex":"Wisata religi tidak boleh ditunggangi doktrin ekstrem; biro seperti itu wajib dilaporkan."},
{"id":"TKP-3418", "q":"Minimarket memasang poster lowongan kerja yang ternyata syaratnya mengikuti 'pembinaan' paham intoleran. Anda pencari kerja. Sikap Anda?", "opts":[{"t":"Melaporkan modus itu ke aparat/disnaker.","s":5},{"t":"Memperingatkan pencari kerja lain.","s":4},{"t":"Mengabaikan lowongan itu.","s":3},{"t":"Melamar dengan alasan butuh kerja.","s":2},{"t":"Ikut pembinaannya demi pekerjaan.","s":1}], "ex":"Lowongan kerja tidak boleh dijadikan umpan paham intoleran; wajib dilaporkan."},
{"id":"TKP-3419", "q":"Klinik pratama menolak pasien beda keyakinan dengan dalih paham intoleran yang dianut pemiliknya. Anda pasien yang menyaksikan. Sikap Anda?", "opts":[{"t":"Melaporkan ke dinas kesehatan agar ditindak.","s":5},{"t":"Menuntut klinik melayani semua pasien.","s":4},{"t":"Pindah ke klinik lain.","s":3},{"t":"Memaklumi kebijakan pemilik.","s":2},{"t":"Ikut membenarkan penolakannya.","s":1}], "ex":"Fasilitas kesehatan wajib melayani tanpa diskriminasi keyakinan; pelanggaran wajib dilaporkan."},
{"id":"TKP-3420", "q":"Dukun bayi menawarkan jasa persalinan yang diselingi ritual 'sumpah setia perjuangan' berpaham ekstrem. Anda keluarga pasien. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke aparat/dinas kesehatan.","s":5},{"t":"Menasihati agar tidak mencampur ritual dengan paham.","s":4},{"t":"Mencari dukun lain.","s":3},{"t":"Mengikuti ritualnya demi keselamatan ibu.","s":2},{"t":"Ikut bersumpah dalam ritual itu.","s":1}], "ex":"Layanan kesehatan tradisional tidak boleh ditunggangi paham ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3421", "q":"Tukang cukur keliling menyebarkan paham intoleran kepada pelanggannya sambil mencukur. Anda pelanggan. Sikap Anda?", "opts":[{"t":"Menegur dan melaporkan bila ia terus menyebarkan.","s":5},{"t":"Meminta agar tidak membahas paham saat bekerja.","s":4},{"t":"Pindah ke tukang cukur lain.","s":3},{"t":"Mendengarkan sambil dicukur.","s":2},{"t":"Ikut menyebarkan ke pelanggan lain.","s":1}], "ex":"Jasa apapun tidak boleh dipakai menyebar paham intoleran; pelanggan berhak menegur dan melapor."},
{"id":"TKP-3422", "q":"Montir panggilan menawarkan servis murah dengan syarat pemilik kendaraan mengikuti kajian kelompok ekstrem. Anda pelanggan. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan modus itu ke aparat.","s":5},{"t":"Menasihati montir agar berhenti.","s":4},{"t":"Tidak memakai jasanya lagi.","s":3},{"t":"Tetap memakai karena murahnya.","s":2},{"t":"Ikut kajiannya demi servis murah.","s":1}], "ex":"Jasa tidak boleh dijadikan umpan rekrutmen paham ekstrem; modusnya wajib dilaporkan."},
{"id":"TKP-3423", "q":"Buruh pabrik diajak mogok kerja oleh provokator yang menunggangi isu intoleransi untuk melawan perusahaan. Anda buruh. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan provokator ke serikat/aparat.","s":5},{"t":"Menasihati rekan agar tidak terprovokasi.","s":4},{"t":"Tidak ikut tanpa berkomentar.","s":3},{"t":"Ikut mogok demi solidaritas.","s":2},{"t":"Ikut memprovokasi buruh lain.","s":1}], "ex":"Isu intoleransi tidak boleh ditunggangi untuk provokasi; buruh wajib menolak dan melapor."},
{"id":"TKP-3424", "q":"Ojek pangkalan diajak 'kopdar wajib' yang ternyata baiat kelompok berpaham khilafah. Anda anggota pangkalan. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan kegiatan baiat ke aparat.","s":5},{"t":"Menasihati koordinator agar menghentikan kegiatan itu.","s":4},{"t":"Tidak datang tanpa penjelasan.","s":3},{"t":"Datang sekadar absen.","s":2},{"t":"Ikut baiat karena sungkan.","s":1}], "ex":"Baiat ke kelompok khilafah adalah pintu terorisme; wajib ditolak dan dilaporkan."},
{"id":"TKP-3425", "q":"Petugas kebersihan kantor diminta menempelkan selebaran propaganda ekstrem di toilet-toilet kantor. Sikap Anda sebagai petugas?", "opts":[{"t":"Menolak dan melaporkan perintah itu ke atasan.","s":5},{"t":"Menolak dengan alasan bukan tugas kebersihan.","s":4},{"t":"Menempel karena takut dipecat.","s":3},{"t":"Menempel dengan alasan perintah.","s":2},{"t":"Ikut menyebarkan selebaran itu.","s":1}], "ex":"Fasilitas kantor tidak boleh ditempeli propaganda ekstrem; perintah seperti itu wajib ditolak dan dilaporkan."}
,
{"id":"TKP-3426", "q":"Office boy diminta mengantar paket mencurigakan berisi selebaran propaganda khilafah ke tiap ruangan. Sikap Anda?", "opts":[{"t":"Menolak mengantar dan melaporkan perintah itu ke atasan.","s":5},{"t":"Menolak dengan alasan bukan tugasnya.","s":4},{"t":"Mengantar karena takut dimarahi.","s":3},{"t":"Mengantar dengan alasan perintah atasan.","s":2},{"t":"Ikut membagikan selebaran itu.","s":1}], "ex":"Kantor tidak boleh menjadi jalur distribusi propaganda khilafah; perintah wajib ditolak dan dilaporkan."},
{"id":"TKP-3427", "q":"Tenaga kebun sekolah diajak iuran oleh senior untuk 'dana perjuangan' kelompok intoleran. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan itu ke kepala sekolah.","s":5},{"t":"Menasihati senior agar berhenti menggalang dana.","s":4},{"t":"Menolak diam-diam.","s":3},{"t":"Ikut iuran agar tidak dikucilkan.","s":2},{"t":"Ikut menggalang iuran.","s":1}], "ex":"Iuran untuk kelompok intoleran adalah pendanaan ekstremisme; wajib ditolak dan dilaporkan."},
{"id":"TKP-3428", "q":"Guru PPPK baru diajak seniornya menyebarkan ujaran intoleran di grup guru. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke kepala sekolah/dinas pendidikan.","s":5},{"t":"Menolak dan menjaga jarak dari ajakan itu.","s":4},{"t":"Diam tanpa memihak.","s":3},{"t":"Ikut menyebar agar diterima.","s":2},{"t":"Aktif menyebarkan ujaran itu.","s":1}], "ex":"Guru tidak boleh menyebar ujaran intoleran; ajakan wajib ditolak dan dilaporkan."},
{"id":"TKP-3429", "q":"Pemeriksa menemukan indikasi dana hibah mengalir ke organisasi berpaham ekstrem, lalu pimpinannya meminta temuan dikecilkan. Sikap Anda?", "opts":[{"t":"Tetap melaporkan temuan apa adanya ke jenjang yang berwenang.","s":5},{"t":"Mencatat temuan resmi dan menolak mengecilkannya.","s":4},{"t":"Mengikuti permintaan pimpinan.","s":3},{"t":"Menghapus temuan dari laporan.","s":2},{"t":"Ikut menutupi aliran dana.","s":1}], "ex":"Integritas pemeriksa tidak boleh dikalahkan tekanan; temuan dana ekstrem wajib dilaporkan."},
{"id":"TKP-3430", "q":"Penyuluh agama menemukan jamaah binaannya diajak kelompok ekstrem untuk memusuhi pemerintah. Tindakan Anda?", "opts":[{"t":"Memberi pembinaan tandingan dan melaporkan kelompok itu ke aparat.","s":5},{"t":"Menasihati jamaah agar tidak terpengaruh.","s":4},{"t":"Fokus pada materi penyuluhan saja.","s":3},{"t":"Membiarkan karena di luar tugas.","s":2},{"t":"Ikut menghadiri ajakan kelompok itu.","s":1}], "ex":"Jamaah binaan wajib dilindungi dari paham ekstrem; penyuluh harus membina dan melapor."},
{"id":"TKP-3431", "q":"Warga melapor kepada Anda sebagai Bhabinkamtibmas tentang ceramah intoleran yang menghasut di wilayah binaan. Tindakan Anda?", "opts":[{"t":"Menindaklanjuti dengan penyelidikan dan koordinasi ke polsek.","s":5},{"t":"Mendatangi lokasi untuk pembinaan dan peringatan.","s":4},{"t":"Mencatat tanpa tindak lanjut.","s":3},{"t":"Menganggapnya laporan biasa.","s":2},{"t":"Membocorkan identitas pelapor.","s":1}], "ex":"Laporan ceramah intoleran wajib ditindaklanjuti aparat keamanan lewat prosedur resmi."},
{"id":"TKP-3432", "q":"Bendahara desa diminta mencairkan dana untuk kegiatan kelompok yang menyebarkan paham khilafah. Sikap Anda?", "opts":[{"t":"Menolak mencairkan dan melaporkan ke kepala desa/inspektorat.","s":5},{"t":"Menolak dengan alasan kegiatan tidak sesuai APBDes.","s":4},{"t":"Mencairkan karena perintah atasan.","s":3},{"t":"Mencairkan agar tidak dimusuhi.","s":2},{"t":"Ikut mengelola dana kegiatan itu.","s":1}], "ex":"Dana desa tidak boleh dicairkan untuk paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3433", "q":"Kaur perencanaan diminta memasukkan program 'pembinaan' bermuatan doktrin ekstrem ke RPJMDes. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke kepala desa/camat.","s":5},{"t":"Menolak dengan alasan tidak sesuai prioritas desa.","s":4},{"t":"Memasukkan dengan alasan perintah.","s":3},{"t":"Memasukkan agar aman.","s":2},{"t":"Ikut menyusun programnya.","s":1}], "ex":"Dokumen perencanaan desa tidak boleh disusupi doktrin ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3434", "q":"Perangkat dusun diajak menghadiri deklarasi dukungan untuk organisasi terlarang karena paham ekstremnya. Sikap Anda?", "opts":[{"t":"Menolak hadir dan melaporkan undangan itu ke aparat.","s":5},{"t":"Menolak dengan alasan netralitas perangkat.","s":4},{"t":"Hadir sekadar melihat-lihat.","s":3},{"t":"Hadir karena diundang tokoh.","s":2},{"t":"Ikut deklarasi dan bersumpah.","s":1}], "ex":"Aparatur tidak boleh menghadiri deklarasi organisasi terlarang; wajib ditolak dan dilaporkan."},
{"id":"TKP-3435", "q":"Satpam kompleks perumahan diminta membiarkan selebaran propaganda teroris ditempel di tembok kompleks. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pengelola/aparat.","s":5},{"t":"Menolak dan mencopot selebaran yang sudah ditempel.","s":4},{"t":"Membiarkan karena takut.","s":3},{"t":"Membiarkan dengan alasan bukan wewenang.","s":2},{"t":"Ikut menempel selebaran.","s":1}], "ex":"Lingkungan hunian wajib steril dari propaganda teroris; satpam wajib menolak dan melapor."},
{"id":"TKP-3436", "q":"Pengurus musholla terminal diminta memutar ceramah intoleran yang provokatif setiap waktu shalat. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pengelola terminal/aparat.","s":5},{"t":"Menolak dengan alasan musholla untuk ibadah.","s":4},{"t":"Membiarkan karena penumpang ramai.","s":3},{"t":"Menganggapnya dakwah biasa.","s":2},{"t":"Ikut memutar ceramahnya.","s":1}], "ex":"Fasilitas ibadah publik tidak boleh dipakai untuk ceramah intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3437", "q":"Vihara didatangi kelompok intoleran yang menuntut pembatasan kegiatan ibadah. Anda pengurus vihara. Sikap Anda?", "opts":[{"t":"Menolak tuntutan dan melaporkan ke aparat penegak hukum.","s":5},{"t":"Berkoordinasi dengan aparat untuk pengamanan.","s":4},{"t":"Mengurangi kegiatan agar tidak ribut.","s":3},{"t":"Menuruti tuntutan demi keamanan.","s":2},{"t":"Ikut membenarkan tuntutan itu.","s":1}], "ex":"Kebebasan beribadah dilindungi undang-undang; tuntutan intoleran wajib ditolak dan dilaporkan."},
{"id":"TKP-3438", "q":"Tetua kampung diminta merestui pendirian 'pesantren' yang ternyata pusat doktrin paham khilafah. Sikap Anda?", "opts":[{"t":"Menolak merestui dan melaporkan ke aparat desa.","s":5},{"t":"Menolak dengan alasan belum jelas izinnya.","s":4},{"t":"Merestui agar tidak dimusuhi.","s":3},{"t":"Merestui karena membawa nama agama.","s":2},{"t":"Ikut menjadi penasihatnya.","s":1}], "ex":"Pendirian pusat doktrin khilafah wajib dicegah; tetua kampung harus menolak dan melapor."},
{"id":"TKP-3439", "q":"Ketua pemuda dusun diajak menjadi 'panglima' laskar kelompok berpaham ekstrem. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan itu ke aparat.","s":5},{"t":"Menolak dan memperingatkan pemuda dusun lain.","s":4},{"t":"Menolak halus tanpa melapor.","s":3},{"t":"Menerima karena gengsi jabatan.","s":2},{"t":"Aktif memimpin laskar itu.","s":1}], "ex":"Pemuda tidak boleh dijadikan panglima paham ekstrem; ajakan wajib ditolak dan dilaporkan."},
{"id":"TKP-3440", "q":"Remaja masjid diajak 'pelatihan kepemimpinan' yang ternyata indoktrinasi paham intoleran. Anda pembina remaja masjid. Sikap Anda?", "opts":[{"t":"Membatalkan kerja sama dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menarik remaja dari pelatihan itu.","s":4},{"t":"Membiarkan karena pesertanya antusias.","s":3},{"t":"Menganggapnya pelatihan biasa.","s":2},{"t":"Ikut mendukung pelatihannya.","s":1}], "ex":"Remaja masjid tidak boleh diindoktrinasi paham intoleran; pembina wajib bertindak dan melapor."},
{"id":"TKP-3441", "q":"Dasawisma diajak menggalang dana untuk 'korban perjuangan' yang ternyata keluarga narapidana terorisme. Anda ketua dasawisma. Sikap Anda?", "opts":[{"t":"Menolak penggalangan dan melaporkan ke aparat.","s":5},{"t":"Menegur penggagas agar menghentikan.","s":4},{"t":"Tidak ikut tanpa protes.","s":3},{"t":"Ikut menyumbang karena kasihan.","s":2},{"t":"Ikut menggalang dana.","s":1}], "ex":"Dana untuk keluarga teroris adalah pendanaan terorisme; wajib ditolak dan dilaporkan."},
{"id":"TKP-3442", "q":"Posbindu lansia disusupi pembagian obat gratis yang diselingi ceramah doktrin ekstrem. Anda kader. Tindakan Anda?", "opts":[{"t":"Menghentikan kegiatan dan melaporkan ke puskesmas/aparat.","s":5},{"t":"Menegur penyelenggara agar fokus pada kesehatan.","s":4},{"t":"Tetap membagikan obatnya.","s":3},{"t":"Menganggapnya bonus penyuluhan.","s":2},{"t":"Ikut menyebarkan ceramahnya.","s":1}], "ex":"Layanan kesehatan tidak boleh ditunggangi doktrin ekstrem; kader wajib menghentikan dan melapor."},
{"id":"TKP-3443", "q":"Kader KB diminta mendata ibu-ibu untuk 'kelas parenting' yang ternyata rekrutmen paham khilafah. Sikap Anda?", "opts":[{"t":"Menolak mendata dan melaporkan ke koordinator/aparat.","s":5},{"t":"Menolak dengan alasan data dilindungi.","s":4},{"t":"Mendata sebagian agar tidak dimusuhi.","s":3},{"t":"Mendata karena perintah.","s":2},{"t":"Aktif membantu rekrutmen.","s":1}], "ex":"Data warga tidak boleh dipakai untuk rekrutmen paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3444", "q":"Guru TK mengajarkan anak didiknya ujaran intoleran untuk memusuhi teman yang berbeda keyakinan. Anda orang tua murid. Sikap Anda?", "opts":[{"t":"Melaporkan ke kepala sekolah dan dinas pendidikan.","s":5},{"t":"Menegur guru agar menghentikan ajarannya.","s":4},{"t":"Memindahkan anak tanpa protes.","s":3},{"t":"Membiarkan karena anak masih kecil.","s":2},{"t":"Ikut mengajarkan di rumah.","s":1}], "ex":"Anak TK tidak boleh diajari memusuhi beda keyakinan; orang tua wajib melapor."},
{"id":"TKP-3445", "q":"Mubaligh keliling menawarkan ceramah gratis yang isinya hasutan intoleran dan ajakan memusuhi pemerintah. Anda tuan rumah yang ditawari. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke tokoh masyarakat/aparat.","s":5},{"t":"Menolak dengan alasan jadwal sudah penuh.","s":4},{"t":"Menerima karena gratis.","s":3},{"t":"Menerima dengan alasan menghormati tamu.","s":2},{"t":"Ikut menyebarkan jadwal ceramahnya.","s":1}], "ex":"Ceramah keliling tidak boleh menjadi sarana hasutan intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3446", "q":"Pengasuh majelis taklim menyisipkan doktrin khilafah dalam setiap pengajian rutin. Anda jamaah. Sikap Anda?", "opts":[{"t":"Melaporkan ke tokoh masyarakat/aparat agar dievaluasi.","s":5},{"t":"Menegur pengasuh agar kembali ke materi yang benar.","s":4},{"t":"Pindah pengajian tanpa protes.","s":3},{"t":"Tetap hadir demi silaturahmi.","s":2},{"t":"Ikut menyebarkan doktrinnya.","s":1}], "ex":"Majelis taklim tidak boleh disusupi doktrin khilafah; jamaah wajib melapor."},
{"id":"TKP-3447", "q":"Suster di panti asuhan katolik ditekan kelompok intoleran agar panti menutup kegiatan ibadahnya. Anda pengurus panti. Sikap Anda?", "opts":[{"t":"Menolak tekanan dan melaporkan ke aparat penegak hukum.","s":5},{"t":"Berkoordinasi dengan aparat untuk perlindungan.","s":4},{"t":"Mengurangi kegiatan ibadah agar aman.","s":3},{"t":"Menuruti tekanan demi keamanan anak panti.","s":2},{"t":"Ikut membenarkan tekanan itu.","s":1}], "ex":"Kebebasan beribadah anak panti dilindungi; tekanan intoleran wajib ditolak dan dilaporkan."},
{"id":"TKP-3448", "q":"Panti disabilitas menerima 'donatur' yang mensyaratkan penghuninya mengikuti pembinaan berpaham ekstrem. Anda pengurus. Sikap Anda?", "opts":[{"t":"Menolak donasi dan melaporkan ke dinas sosial/aparat.","s":5},{"t":"Menolak syaratnya dan mencari donatur lain.","s":4},{"t":"Menerima karena panti butuh dana.","s":3},{"t":"Menerima dengan alasan keterpaksaan.","s":2},{"t":"Ikut menjalankan pembinaannya.","s":1}], "ex":"Kelompok rentan tidak boleh dieksploitasi paham ekstrem lewat donasi; wajib ditolak dan dilaporkan."},
{"id":"TKP-3449", "q":"Pengurus langgar diminta menyediakan tempat untuk baiat anggota baru kelompok berpaham khilafah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke takmir/aparat.","s":5},{"t":"Menolak dengan alasan langgar untuk ibadah.","s":4},{"t":"Memberi tempat agar tidak ribut.","s":3},{"t":"Memberi tempat karena dibayar.","s":2},{"t":"Ikut menghadiri baiatnya.","s":1}], "ex":"Tempat ibadah tidak boleh dipakai untuk baiat paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3450", "q":"Muadzin diminta mengumandangkan seruan provokatif bernada intoleran lewat pengeras suara masjid. Sikap Anda sebagai muadzin?", "opts":[{"t":"Menolak dan melaporkan permintaan itu ke takmir/aparat.","s":5},{"t":"Menolak dengan alasan pengeras suara untuk adzan.","s":4},{"t":"Menuruti sekali agar tidak dimusuhi.","s":3},{"t":"Menuruti karena perintah pengurus.","s":2},{"t":"Ikut mengumandangkan dengan semangat.","s":1}], "ex":"Pengeras suara masjid tidak boleh dipakai untuk provokasi intoleran; wajib ditolak dan dilaporkan."}
,
{"id":"TKP-3451", "q":"Ketua RT diminta menyerahkan data warga untuk 'verifikasi akidah' oleh kelompok intoleran. Sikap Anda sebagai ketua RT?", "opts":[{"t":"Menolak menyerahkan data dan melaporkan permintaan itu ke lurah/aparat.","s":5},{"t":"Menolak dengan alasan data warga dilindungi.","s":4},{"t":"Menyerahkan sebagian agar tidak dimusuhi.","s":3},{"t":"Menyerahkan karena diminta baik-baik.","s":2},{"t":"Aktif membantu verifikasi itu.","s":1}], "ex":"Data warga tidak boleh dipakai untuk verifikasi akidah kelompok intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3452", "q":"Portal RW akan ditutup untuk razia 'razia akidah' oleh sekelompok warga intoleran. Anda ketua RW. Tindakan Anda?", "opts":[{"t":"Melarang razia dan melaporkan rencananya ke aparat.","s":5},{"t":"Menegur penggagas agar menghentikan rencana.","s":4},{"t":"Membiarkan karena tidak mau berkonflik.","s":3},{"t":"Mendukung dengan alasan ketertiban.","s":2},{"t":"Ikut memimpin razia.","s":1}], "ex":"Razia berdasar keyakinan adalah tindakan intoleran yang melanggar hukum; wajib dilarang dan dilaporkan."},
{"id":"TKP-3453", "q":"Petugas PKH menemukan keluarga penerima bantuan yang anaknya direkrut paham ekstrem lewat grup media sosial. Tindakan Anda?", "opts":[{"t":"Melaporkan temuan itu ke koordinator dan aparat untuk pembinaan.","s":5},{"t":"Memberi edukasi ke keluarga tentang bahaya paham tersebut.","s":4},{"t":"Fokus pada penyaluran bantuan saja.","s":3},{"t":"Menganggapnya di luar tugas.","s":2},{"t":"Ikut bergabung ke grup itu.","s":1}], "ex":"Temuan rekrutmen paham ekstrem saat bertugas wajib dilaporkan agar ada pembinaan."},
{"id":"TKP-3454", "q":"Relawan PMI menemukan donor yang menyebarkan paham intoleran di sela kegiatan donor darah. Anda koordinator relawan. Sikap Anda?", "opts":[{"t":"Menegur dan bila berlanjut melaporkan ke pengurus/aparat.","s":5},{"t":"Meminta yang bersangkutan fokus pada kegiatan kemanusiaan.","s":4},{"t":"Membiarkan karena ia rajin donor.","s":3},{"t":"Menganggapnya hak berpendapat.","s":2},{"t":"Ikut menyebarkan pahamnya.","s":1}], "ex":"Kegiatan kemanusiaan tidak boleh disusupi paham intoleran; koordinator wajib menertibkan."},
{"id":"TKP-3455", "q":"Petugas parkir resmi diminta menyisihkan hasil retribusi untuk 'dana perjuangan' kelompok intoleran. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pengelola/aparat.","s":5},{"t":"Menolak dengan alasan retribusi untuk kas daerah.","s":4},{"t":"Menyisihkan sedikit agar aman.","s":3},{"t":"Menyisihkan karena perintah koordinator.","s":2},{"t":"Aktif mengutip untuk kelompok itu.","s":1}], "ex":"Retribusi resmi tidak boleh disisihkan untuk paham intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3456", "q":"Petugas bea cukai menemukan kiriman buku-buku paham khilafah dalam jumlah besar dari luar negeri. Tindakan Anda?", "opts":[{"t":"Menahan kiriman dan melaporkan ke atasan/aparat keamanan.","s":5},{"t":"Mendalami dokumen kiriman sesuai prosedur.","s":4},{"t":"Meloloskan karena terlihat seperti buku biasa.","s":3},{"t":"Membiarkan dengan alasan bukan wewenang.","s":2},{"t":"Ikut mengambil bukunya.","s":1}], "ex":"Impor massal buku paham khilafah wajib ditahan dan dilaporkan ke aparat keamanan."},
{"id":"TKP-3457", "q":"Posko mudik lebaran dipakai sekelompok orang untuk menyebarkan selebaran propaganda teroris kepada pemudik. Anda petugas posko. Tindakan Anda?", "opts":[{"t":"Mengusir penyebar dan melaporkan ke aparat keamanan.","s":5},{"t":"Menegur dan menyita selebarannya.","s":4},{"t":"Membiarkan karena posko ramai.","s":3},{"t":"Menganggapnya bukan wewenang.","s":2},{"t":"Ikut membagikan selebaran.","s":1}], "ex":"Fasilitas publik mudik wajib steril dari propaganda teroris; petugas wajib menindak."},
{"id":"TKP-3458", "q":"Petugas rutan menemukan tahanan yang mengindoktrinasi tahanan lain dengan paham khilafah. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pimpinan rutan agar pelaku dipisahkan dan dibina.","s":5},{"t":"Menegur dan memperketat pengawasan blok.","s":4},{"t":"Menganggapnya urusan antar-tahanan.","s":3},{"t":"Membiarkan karena takut.","s":2},{"t":"Ikut mendengarkan indoktrinasinya.","s":1}], "ex":"Indoktrinasi paham khilafah di rutan wajib ditindak lewat pemisahan dan pembinaan resmi."},
{"id":"TKP-3459", "q":"Pustu (puskesmas pembantu) dipakai oknum untuk rapat tertutup kelompok berpaham ekstrem tiap pekan. Anda bidan koordinator. Tindakan Anda?", "opts":[{"t":"Melarang pemakaian dan melaporkan ke puskesmas induk/aparat.","s":5},{"t":"Menegur oknum agar tidak mengulangi.","s":4},{"t":"Membiarkan karena di luar jam layanan.","s":3},{"t":"Menganggapnya bukan urusan.","s":2},{"t":"Ikut menghadiri rapatnya.","s":1}], "ex":"Fasilitas kesehatan tidak boleh dipakai rapat paham ekstrem; wajib dilarang dan dilaporkan."},
{"id":"TKP-3460", "q":"Ajudan pejabat diminta mengatur jadwal pertemuan tertutup antara pejabatnya dengan tokoh kelompok berpaham khilafah. Sikap Anda?", "opts":[{"t":"Menolak mengatur dan melaporkan permintaan itu ke atasan/aparat.","s":5},{"t":"Menolak dengan alasan jadwal dinas.","s":4},{"t":"Mengatur karena perintah.","s":3},{"t":"Mengatur agar tidak dimarahi.","s":2},{"t":"Ikut memfasilitasi pertemuan.","s":1}], "ex":"Jabatan publik tidak boleh difasilitasi untuk kelompok khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3461", "q":"Koperasi karyawan diminta menjadi penyalur 'wakaf perjuangan' yang ternyata untuk jaringan kelompok ekstrem. Anda pengurus. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pengawas koperasi/aparat.","s":5},{"t":"Menolak dengan alasan tidak sesuai AD/ART.","s":4},{"t":"Menyalurkan karena desakan anggota.","s":3},{"t":"Menyalurkan dengan alasan ibadah.","s":2},{"t":"Aktif menggalang wakaf itu.","s":1}], "ex":"Koperasi tidak boleh menjadi penyalur dana jaringan ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3462", "q":"Infak Jumat di kantor dikelola oknum yang menyalurkannya ke kelompok intoleran. Anda jamaah. Sikap Anda?", "opts":[{"t":"Melaporkan penyelewengan itu ke takmir/pimpinan/aparat.","s":5},{"t":"Menegur pengelola agar transparan.","s":4},{"t":"Berhenti berinfak tanpa protes.","s":3},{"t":"Tetap berinfak dengan alasan niat.","s":2},{"t":"Ikut menggalang infak itu.","s":1}], "ex":"Dana infak yang diselewengkan ke kelompok intoleran wajib dilaporkan; transparansi wajib dituntut."},
{"id":"TKP-3463", "q":"Klub badminton pegawai direkrut pelatihnya menjadi jaringan penyebaran paham intoleran. Anda anggota klub. Sikap Anda?", "opts":[{"t":"Keluar dari klub dan melaporkan perekrutan itu ke pimpinan/aparat.","s":5},{"t":"Menolak ikut dan memperingatkan anggota lain.","s":4},{"t":"Berhenti latihan tanpa penjelasan.","s":3},{"t":"Tetap main demi olahraga.","s":2},{"t":"Ikut bergabung jaringannya.","s":1}], "ex":"Komunitas olahraga tidak boleh direkrut menjadi jaringan paham intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3464", "q":"Mading sekolah ditempeli poster propaganda khilafah oleh sekelompok siswa. Anda guru. Tindakan Anda?", "opts":[{"t":"Mencopot poster dan membina siswa itu serta melaporkan ke kepala sekolah.","s":5},{"t":"Menegur siswa dan memberi pembinaan wawasan kebangsaan.","s":4},{"t":"Membiarkan karena karya siswa.","s":3},{"t":"Menganggapnya ekspresi biasa.","s":2},{"t":"Ikut memajang poster serupa.","s":1}], "ex":"Sekolah wajib steril dari propaganda khilafah; guru harus menertibkan dan membina siswanya."},
{"id":"TKP-3465", "q":"Mahasiswa Indonesia di luar negeri diajak seniornya bergabung sel kelompok ekstrem yang memusuhi NKRI. Anda mahasiswa itu. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke KBRI/aparat Indonesia.","s":5},{"t":"Menolak dan memperingatkan mahasiswa Indonesia lain.","s":4},{"t":"Menolak diam-diam.","s":3},{"t":"Ikut agar tidak dikucilkan diaspora.","s":2},{"t":"Aktif bergabung dalam sel itu.","s":1}], "ex":"Diaspora Indonesia tidak boleh direkrut paham anti-NKRI; wajib ditolak dan dilaporkan ke KBRI."},
{"id":"TKP-3466", "q":"Platform galang dana online dipakai untuk mengumpulkan 'donasi kemanusiaan' yang ternyata untuk narapidana terorisme. Anda donatur yang mengetahui. Sikap Anda?", "opts":[{"t":"Melaporkan kampanye itu ke platform dan aparat penegak hukum.","s":5},{"t":"Menarik donasi dan memperingatkan donatur lain.","s":4},{"t":"Berhenti berdonasi tanpa melapor.","s":3},{"t":"Tetap berdonasi karena kasihan.","s":2},{"t":"Ikut menyebarkan kampanyenya.","s":1}], "ex":"Galang dana untuk teroris adalah pendanaan terorisme; wajib dilaporkan ke platform dan aparat."},
{"id":"TKP-3467", "q":"Calon pengantin (catin) yang mengikuti bimbingan pranikah di KUA ternyata menyebarkan paham khilafah ke peserta lain. Anda penyuluh. Tindakan Anda?", "opts":[{"t":"Menegur dan bila berlanjut melaporkan ke pimpinan KUA/aparat.","s":5},{"t":"Memberi pembinaan wawasan kebangsaan kepada peserta.","s":4},{"t":"Fokus pada materi pranikah saja.","s":3},{"t":"Membiarkan karena sesama peserta.","s":2},{"t":"Ikut menyebarkan pahamnya.","s":1}], "ex":"Bimbingan pranikah tidak boleh disusupi paham khilafah; penyuluh wajib menertibkan dan melapor."},
{"id":"TKP-3468", "q":"Pewawancara sensus pertanian menemukan kelompok tani yang menolak didata karena menganggap sensus 'program thagut' kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Tetap profesional, mencatat, dan melaporkan ke koordinator/aparat.","s":5},{"t":"Berkordinasi dengan aparat desa untuk pendampingan.","s":4},{"t":"Melewati kelompok itu.","s":3},{"t":"Memaksa dengan kasar.","s":2},{"t":"Ikut membenarkan penolakan.","s":1}], "ex":"Penolakan berlabel ekstrem wajib dicatat dan dilaporkan; petugas tetap profesional."},
{"id":"TKP-3469", "q":"Madrasah diniyah di kampung Anda disusupi guru baru yang mengajarkan paham intoleran kepada santri. Anda orang tua santri. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola madrasah dan Kemenag/aparat.","s":5},{"t":"Menegur pengelola agar mengevaluasi guru itu.","s":4},{"t":"Memindahkan anak tanpa protes.","s":3},{"t":"Membiarkan karena urusan madrasah.","s":2},{"t":"Ikut mendukung guru baru itu.","s":1}], "ex":"Madrasah tidak boleh disusupi paham intoleran; orang tua wajib melapor ke pihak berwenang."},
{"id":"TKP-3470", "q":"Petugas keamanan sebuah event diminta membiarkan orasi intoleran yang provokatif demi 'kelancaran acara'. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke penanggung jawab acara/aparat.","s":5},{"t":"Menolak dengan alasan keamanan pengunjung.","s":4},{"t":"Membiarkan karena perintah panitia.","s":3},{"t":"Membiarkan demi kelancaran.","s":2},{"t":"Ikut mengamankan sambil mendukung orasi.","s":1}], "ex":"Keamanan event tidak boleh menjadi tameng orasi intoleran; petugas wajib menolak dan melapor."},
{"id":"TKP-3471", "q":"Kelompok wirid diajak ziarah massal yang ternyata dimanfaatkan untuk orasi paham khilafah. Anda anggota wirid. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menasihati koordinator agar menghentikan pemanfaatan itu.","s":4},{"t":"Tidak ikut tanpa penjelasan.","s":3},{"t":"Ikut ziarah tanpa peduli orasinya.","s":2},{"t":"Ikut berorasi mendukung.","s":1}], "ex":"Kegiatan keagamaan tidak boleh dimanfaatkan untuk orasi paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3472", "q":"Kurir paket diminta mengantar 'paket dakwah' berisi buku-buku paham ekstrem ke berbagai alamat. Sikap Anda sebagai kurir?", "opts":[{"t":"Menolak mengantar dan melaporkan ke perusahaan/aparat.","s":5},{"t":"Menolak dengan alasan isi paket mencurigakan.","s":4},{"t":"Mengantar karena tugas.","s":3},{"t":"Mengantar demi insentif.","s":2},{"t":"Ikut membaca dan menyebarkan bukunya.","s":1}], "ex":"Jasa kurir tidak boleh dipakai mendistribusikan paham ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3473", "q":"Kantin sekolah menjual majalah anak yang diselingi komik propaganda intoleran. Anda guru. Tindakan Anda?", "opts":[{"t":"Melarang peredaran dan melaporkan ke kepala sekolah/dinas.","s":5},{"t":"Menegur pengelola kantin agar menarik majalah itu.","s":4},{"t":"Melarang murid membeli tanpa protes resmi.","s":3},{"t":"Membiarkan karena laris.","s":2},{"t":"Ikut membagikannya.","s":1}], "ex":"Bacaan anak tidak boleh disusupi propaganda intoleran; guru wajib melarang dan melapor."},
{"id":"TKP-3474", "q":"Satpam bank diminta membiarkan kotak donasi 'perjuangan' kelompok intoleran di area ATM. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pimpinan bank/aparat.","s":5},{"t":"Menolak dengan alasan area bank steril.","s":4},{"t":"Membiarkan karena takut.","s":3},{"t":"Membiarkan dengan alasan kemanusiaan.","s":2},{"t":"Ikut berdonasi ke kotak itu.","s":1}], "ex":"Fasilitas publik tidak boleh dipakai menggalang dana paham intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3475", "q":"Siswa PKL SMK di perusahaan Anda menyebarkan video propaganda teroris ke grup karyawan. Anda pembimbing. Tindakan Anda?", "opts":[{"t":"Menegur, membina, dan melaporkan ke sekolah/perusahaan bila berlanjut.","s":5},{"t":"Memberi pembinaan langsung tentang bahayanya.","s":4},{"t":"Mengeluarkannya dari grup saja.","s":3},{"t":"Membiarkan karena ia masih siswa.","s":2},{"t":"Ikut menonton videonya.","s":1}], "ex":"Pembimbing wajib membina siswa PKL yang menyebar propaganda teroris, bukan membiarkannya."}
,
{"id":"TKP-3476", "q":"OB diminta memfotokopi selebaran propaganda khilafah untuk disebar ke tiap meja pegawai. Sikap Anda?", "opts":[{"t":"Menolak memfotokopi dan melaporkan perintah itu ke atasan.","s":5},{"t":"Menolak dengan alasan bukan tugasnya.","s":4},{"t":"Memfotokopi karena takut dimarahi.","s":3},{"t":"Memfotokopi dengan alasan perintah.","s":2},{"t":"Ikut menyebarkan selebaran itu.","s":1}], "ex":"Mesin kantor tidak boleh dipakai menggandakan propaganda khilafah; perintah wajib ditolak dan dilaporkan."},
{"id":"TKP-3477", "q":"Guru honorer diajak seniornya menyisipkan paham intoleran dalam pelajaran. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke kepala sekolah.","s":5},{"t":"Menolak dan menjaga materi tetap netral.","s":4},{"t":"Diam tanpa memihak.","s":3},{"t":"Ikut menyisipkan agar diterima senior.","s":2},{"t":"Aktif menyebarkan di kelas.","s":1}], "ex":"Guru honorer tidak boleh menyisipkan paham intoleran; ajakan wajib ditolak dan dilaporkan."},
{"id":"TKP-3478", "q":"Nakes PPPK baru diajak rekan menyebarkan ujaran kebencian intoleran di grup nakes. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pimpinan puskesmas/dinas kesehatan.","s":5},{"t":"Menolak dan menjaga jarak dari ajakan itu.","s":4},{"t":"Diam tanpa memihak.","s":3},{"t":"Ikut menyebar agar diterima.","s":2},{"t":"Aktif menyebarkan ujaran itu.","s":1}], "ex":"Tenaga kesehatan tidak boleh menyebar ujaran intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3479", "q":"Pemeriksa pajak menemukan perusahaan fiktif yang dananya mengalir ke jaringan kelompok ekstrem. Atasan meminta temuan diabaikan. Sikap Anda?", "opts":[{"t":"Tetap melaporkan temuan ke jenjang berwenang/PPATK.","s":5},{"t":"Mencatat temuan resmi dan menolak mengabaikannya.","s":4},{"t":"Mengikuti perintah atasan.","s":3},{"t":"Menghapus temuan.","s":2},{"t":"Ikut menutupi aliran dana.","s":1}], "ex":"Temuan dana ke jaringan ekstrem tidak boleh diabaikan atas perintah siapa pun; wajib dilaporkan."},
{"id":"TKP-3480", "q":"Penyuluh perikanan menemukan kelompok nelayan binaan diajak baiat paham khilafah. Tindakan Anda?", "opts":[{"t":"Mencegah dan melaporkan ke aparat desa/Bhabinkamtibmas.","s":5},{"t":"Memberi penyuluhan tandingan tentang bahayanya.","s":4},{"t":"Fokus pada materi perikanan saja.","s":3},{"t":"Membiarkan karena di luar tugas.","s":2},{"t":"Ikut menghadiri baiatnya.","s":1}], "ex":"Kelompok binaan tidak boleh dibaiat paham khilafah; penyuluh wajib mencegah dan melapor."},
{"id":"TKP-3481", "q":"Polisi RW menerima laporan warga tentang pengajian tertutup berpaham ekstrem di wilayahnya. Tindakan Anda?", "opts":[{"t":"Menindaklanjuti dengan verifikasi dan koordinasi ke polsek.","s":5},{"t":"Mendatangi lokasi untuk pembinaan awal.","s":4},{"t":"Mencatat tanpa tindak lanjut.","s":3},{"t":"Menganggapnya laporan biasa.","s":2},{"t":"Membocorkan identitas pelapor.","s":1}], "ex":"Laporan pengajian berpaham ekstrem wajib ditindaklanjuti aparat lewat prosedur resmi."},
{"id":"TKP-3482", "q":"Kasi pemerintahan diminta menerbitkan rekomendasi kegiatan untuk kelompok yang menyebarkan paham intoleran. Sikap Anda?", "opts":[{"t":"Menolak menerbitkan dan melaporkan ke camat.","s":5},{"t":"Menolak dengan alasan kegiatan tidak memenuhi syarat.","s":4},{"t":"Menerbitkan karena perintah.","s":3},{"t":"Menerbitkan agar tidak ribut.","s":2},{"t":"Ikut mempromosikan kegiatan itu.","s":1}], "ex":"Rekomendasi resmi tidak boleh diterbitkan untuk paham intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3483", "q":"Kaur keuangan diminta memalsukan kwitansi dana kegiatan yang ternyata untuk kelompok berpaham khilafah. Sikap Anda?", "opts":[{"t":"Menolak memalsukan dan melaporkan ke kepala desa/inspektorat.","s":5},{"t":"Menolak dengan alasan integritas keuangan desa.","s":4},{"t":"Memalsukan karena perintah.","s":3},{"t":"Memalsukan agar aman.","s":2},{"t":"Ikut menikmati dana itu.","s":1}], "ex":"Pemalsuan keuangan untuk paham khilafah adalah kejahatan; wajib ditolak dan dilaporkan."},
{"id":"TKP-3484", "q":"Ketua LKMD diajak menjadi penasihat organisasi yang dibubarkan karena paham ekstremnya. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan itu ke aparat desa.","s":5},{"t":"Menolak dengan alasan menjaga netralitas lembaga.","s":4},{"t":"Menerima karena menghormati yang mengajak.","s":3},{"t":"Menerima demi memperluas jaringan.","s":2},{"t":"Aktif menjadi penasihatnya.","s":1}], "ex":"Lembaga desa tidak boleh menjadi penasihat organisasi terlarang; wajib ditolak dan dilaporkan."},
{"id":"TKP-3485", "q":"Pecalang adat diminta mengamankan acara orasi kelompok intoleran yang provokatif. Sikap Anda sebagai pecalang?", "opts":[{"t":"Menolak pengerahan dan melaporkan ke bendesa adat/aparat.","s":5},{"t":"Menolak dengan alasan adat tidak mencampuri.","s":4},{"t":"Mengamankan karena perintah.","s":3},{"t":"Mengamankan demi upah.","s":2},{"t":"Ikut mendukung orasinya.","s":1}], "ex":"Pengamanan adat tidak boleh dipakai untuk orasi intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3486", "q":"Pengurus musala kantor camat diminta memutar ceramah kelompok teroris yang mengagungkan kekerasan. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke camat/aparat.","s":5},{"t":"Menolak dengan alasan musala untuk ibadah.","s":4},{"t":"Membiarkan karena takut.","s":3},{"t":"Menganggapnya dakwah biasa.","s":2},{"t":"Ikut memutar ceramahnya.","s":1}], "ex":"Fasilitas ibadah kantor tidak boleh dipakai untuk ceramah teroris; wajib ditolak dan dilaporkan."},
{"id":"TKP-3487", "q":"Kelenteng didatangi kelompok intoleran yang menuntut penutupan kegiatan ibadah. Anda pengurus kelenteng. Sikap Anda?", "opts":[{"t":"Menolak tuntutan dan melaporkan ke aparat penegak hukum.","s":5},{"t":"Berkoordinasi dengan aparat untuk pengamanan.","s":4},{"t":"Mengurangi kegiatan agar aman.","s":3},{"t":"Menuruti tuntutan demi keamanan.","s":2},{"t":"Ikut membenarkan tuntutan.","s":1}], "ex":"Kebebasan beribadah dilindungi undang-undang; tuntutan intoleran wajib ditolak dan dilaporkan."},
{"id":"TKP-3488", "q":"Damang adat diminta merestui berdirinya markas kelompok berpaham khilafah di wilayah adatnya. Sikap Anda?", "opts":[{"t":"Menolak merestui dan melaporkan ke aparat.","s":5},{"t":"Menolak dengan alasan adat menolak paham itu.","s":4},{"t":"Merestui agar tidak berkonflik.","s":3},{"t":"Merestui karena dijanjikan dana.","s":2},{"t":"Ikut menjadi pelindungnya.","s":1}], "ex":"Wilayah adat tidak boleh menjadi markas paham khilafah; tokoh adat wajib menolak dan melapor."},
{"id":"TKP-3489", "q":"Ketua organisasi kepemudaan diajak berafiliasi dengan jaringan kelompok ekstrem yang anti-NKRI. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan itu ke aparat.","s":5},{"t":"Menolak dan menjaga organisasi tetap netral.","s":4},{"t":"Menolak halus tanpa melapor.","s":3},{"t":"Menerima karena iming-iming dana.","s":2},{"t":"Aktif berafiliasi.","s":1}], "ex":"Organisasi pemuda tidak boleh berafiliasi dengan jaringan anti-NKRI; wajib ditolak dan dilaporkan."},
{"id":"TKP-3490", "q":"Pramuka diajak mengikuti 'jambore' yang ternyata ajang indoktrinasi paham intoleran. Anda pembina pramuka. Sikap Anda?", "opts":[{"t":"Membatalkan keikutsertaan dan melaporkan penyelenggaranya.","s":5},{"t":"Menarik anggota dari kegiatan itu.","s":4},{"t":"Tetap ikut demi pengalaman.","s":3},{"t":"Menganggapnya jambore biasa.","s":2},{"t":"Ikut mendukung penyelenggaranya.","s":1}], "ex":"Pramuka tidak boleh dijadikan ajang indoktrinasi intoleran; pembina wajib bertindak dan melapor."},
{"id":"TKP-3491", "q":"Dharma Wanita diajak menggalang dana untuk 'istri mujahid' yang ternyata keluarga teroris. Anda anggota. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan penggalangan itu ke aparat.","s":5},{"t":"Menasihati penggagas agar menghentikan.","s":4},{"t":"Tidak ikut tanpa protes.","s":3},{"t":"Ikut menyumbang karena kasihan.","s":2},{"t":"Ikut menggalang dana.","s":1}], "ex":"Dana untuk keluarga teroris adalah pendanaan terorisme; wajib ditolak dan dilaporkan."},
{"id":"TKP-3492", "q":"Sanggar belajar anak disusupi tutor yang mengajarkan ujaran kebencian intoleran. Anda orang tua murid. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola sanggar dan dinas pendidikan.","s":5},{"t":"Menegur pengelola agar mengganti tutor.","s":4},{"t":"Memindahkan anak tanpa protes.","s":3},{"t":"Membiarkan karena anak senang.","s":2},{"t":"Ikut mendukung tutornya.","s":1}], "ex":"Sanggar belajar tidak boleh disusupi ujaran intoleran; orang tua wajib melapor."},
{"id":"TKP-3493", "q":"Kader lansia diminta mendata lansia untuk 'bantuan' yang ternyata rekrutmen paham khilafah. Sikap Anda?", "opts":[{"t":"Menolak mendata dan melaporkan ke koordinator/aparat.","s":5},{"t":"Menolak dengan alasan data dilindungi.","s":4},{"t":"Mendata sebagian agar tidak dimusuhi.","s":3},{"t":"Mendata karena perintah.","s":2},{"t":"Aktif membantu rekrutmen.","s":1}], "ex":"Lansia tidak boleh dieksploitasi untuk rekrutmen paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3494", "q":"TPA (taman pendidikan al-Quran) disusupi pengajar yang menanamkan paham ekstrem kepada anak-anak. Anda wali santri. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola TPA dan Kemenag/aparat.","s":5},{"t":"Menegur pengelola agar mengevaluasi pengajar.","s":4},{"t":"Memindahkan anak tanpa protes.","s":3},{"t":"Membiarkan karena urusan TPA.","s":2},{"t":"Ikut mendukung pengajarnya.","s":1}], "ex":"TPA tidak boleh disusupi paham ekstrem; wali santri wajib melapor ke pihak berwenang."},
{"id":"TKP-3495", "q":"Dai kondang yang Anda undang ternyata dalam ceramahnya yang intoleran menghasut jamaah memusuhi pemerintah yang sah. Anda panitia. Sikap Anda?", "opts":[{"t":"Menghentikan ceramah dan melaporkan ke aparat.","s":5},{"t":"Menegur dai agar menghentikan hasutannya.","s":4},{"t":"Membiarkan sampai selesai karena sudah dibayar.","s":3},{"t":"Menganggapnya gaya ceramah biasa.","s":2},{"t":"Ikut menyebarkan rekamannya.","s":1}], "ex":"Penceramah tidak boleh menghasut memusuhi pemerintah yang sah; panitia wajib menghentikan dan melapor."},
{"id":"TKP-3496", "q":"Tuan guru diajak menjadi 'penasihat spiritual' kelompok yang menyebarkan paham khilafah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan itu ke aparat.","s":5},{"t":"Menolak dengan alasan menjaga kemurnian dakwah.","s":4},{"t":"Menerima karena menghormati yang mengajak.","s":3},{"t":"Menerima demi memperluas jamaah.","s":2},{"t":"Aktif menjadi penasihatnya.","s":1}], "ex":"Ulama tidak boleh menjadi penasihat paham khilafah; ajakan wajib ditolak dan dilaporkan."},
{"id":"TKP-3497", "q":"Romo didatangi kelompok intoleran yang menuntut pembatasan misa. Anda umat yang mengetahui. Sikap Anda?", "opts":[{"t":"Mendukung romo menolak dan melaporkan ke aparat.","s":5},{"t":"Berkoordinasi dengan aparat untuk pengamanan gereja.","s":4},{"t":"Meminta misa dikurangi agar aman.","s":3},{"t":"Menuruti tuntutan demi keamanan.","s":2},{"t":"Ikut membenarkan tuntutan.","s":1}], "ex":"Kebebasan beribadah dilindungi; tuntutan intoleran wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3498", "q":"Rumah singgah anak jalanan menerima 'donatur' yang mensyaratkan anak asuh mengikuti pembinaan berpaham ekstrem. Anda pengelola. Sikap Anda?", "opts":[{"t":"Menolak donasi dan melaporkan ke dinas sosial/aparat.","s":5},{"t":"Menolak syaratnya dan mencari donatur lain.","s":4},{"t":"Menerima karena butuh dana.","s":3},{"t":"Menerima dengan alasan keterpaksaan.","s":2},{"t":"Ikut menjalankan pembinaannya.","s":1}], "ex":"Anak jalanan tidak boleh dieksploitasi paham ekstrem lewat donasi; wajib ditolak dan dilaporkan."},
{"id":"TKP-3499", "q":"Pengurus masjid agung ditekan agar menyerahkan mimbar Jumat untuk orasi kelompok intoleran. Sikap Anda sebagai pengurus?", "opts":[{"t":"Menolak tekanan dan melaporkan ke DMI/aparat.","s":5},{"t":"Menolak dengan alasan jadwal khatib resmi.","s":4},{"t":"Menyerahkan sekali agar tidak ribut.","s":3},{"t":"Menyerahkan karena takut.","s":2},{"t":"Ikut mengundang oratornya.","s":1}], "ex":"Mimbar masjid agung tidak boleh direbut untuk orasi intoleran; tekanan wajib ditolak dan dilaporkan."},
{"id":"TKP-3500", "q":"Penjaga musholla sekolah diminta membiarkan kajian tertutup paham khilafah tiap istirahat. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke kepala sekolah.","s":5},{"t":"Menolak dengan alasan musholla untuk ibadah siswa.","s":4},{"t":"Membiarkan karena di luar jam pelajaran.","s":3},{"t":"Membiarkan dengan alasan dibayar.","s":2},{"t":"Ikut menjaga kajiannya.","s":1}], "ex":"Musholla sekolah tidak boleh dipakai kajian paham khilafah; wajib ditolak dan dilaporkan."}
,
{"id":"TKP-3501", "q":"Ketua RT diminta memberi izin keramaian untuk orasi kelompok yang menyebarkan paham intoleran. Sikap Anda?", "opts":[{"t":"Menolak memberi izin dan melaporkan rencana orasi ke lurah/aparat.","s":5},{"t":"Menolak dengan alasan tidak memenuhi syarat ketertiban.","s":4},{"t":"Memberi izin agar tidak dimusuhi.","s":3},{"t":"Memberi izin karena dijanjikan imbalan.","s":2},{"t":"Ikut memfasilitasi orasinya.","s":1}], "ex":"Izin keramaian tidak boleh diterbitkan untuk orasi paham intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3502", "q":"Dana kas RW dipakai bendahara untuk menyumbang kegiatan kelompok berpaham khilafah. Anda warga RW. Sikap Anda?", "opts":[{"t":"Menuntut pertanggungjawaban dan melaporkan ke lurah/aparat.","s":5},{"t":"Memprotes dalam rapat warga.","s":4},{"t":"Diam karena bukan urusan.","s":3},{"t":"Membiarkan dengan alasan seikhlasnya.","s":2},{"t":"Ikut menyumbang kas untuk itu.","s":1}], "ex":"Kas warga tidak boleh dipakai untuk paham khilafah; wajib dituntut dan dilaporkan."},
{"id":"TKP-3503", "q":"Petugas Dukcapil menemukan pemohon KTP yang datanya dipakai untuk perekrutan paham ekstrem. Tindakan Anda?", "opts":[{"t":"Melaporkan temuan itu ke atasan dan aparat berwenang.","s":5},{"t":"Mendalami kejanggalan data sesuai prosedur.","s":4},{"t":"Memproses seperti biasa.","s":3},{"t":"Mengabaikan karena antrean panjang.","s":2},{"t":"Ikut membantu pemalsuannya.","s":1}], "ex":"Temuan penyalahgunaan data untuk paham ekstrem wajib dilaporkan; petugas tetap prosedural."},
{"id":"TKP-3504", "q":"BPBD menemukan posko pengungsian dipakai untuk penyebaran paham intoleran oleh oknum relawan. Anda petugas. Tindakan Anda?", "opts":[{"t":"Menertibkan oknum dan melaporkan ke pimpinan/aparat.","s":5},{"t":"Menegur relawan agar fokus pada kemanusiaan.","s":4},{"t":"Membiarkan karena situasi darurat.","s":3},{"t":"Menganggapnya bukan prioritas.","s":2},{"t":"Ikut menyebarkan pahamnya.","s":1}], "ex":"Posko bencana wajib steril dari paham intoleran; petugas wajib menertibkan dan melapor."},
{"id":"TKP-3505", "q":"Petugas pasar diminta memungut 'retribusi perjuangan' untuk kelompok intoleran dari pedagang. Sikap Anda?", "opts":[{"t":"Menolak memungut dan melaporkan ke pengelola/aparat.","s":5},{"t":"Menolak dengan alasan pungutan tidak resmi.","s":4},{"t":"Memungut karena perintah koordinator.","s":3},{"t":"Memungut agar aman.","s":2},{"t":"Aktif mengutip untuk kelompok itu.","s":1}], "ex":"Pungutan liar untuk paham intoleran wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3506", "q":"Petugas karantina menemukan kiriman paket berisi materi propaganda teroris. Tindakan Anda?", "opts":[{"t":"Menahan paket dan melaporkan ke atasan/aparat keamanan.","s":5},{"t":"Mendalami isi kiriman sesuai prosedur.","s":4},{"t":"Meloloskan karena terlihat seperti paket biasa.","s":3},{"t":"Membiarkan dengan alasan bukan wewenang.","s":2},{"t":"Ikut mengambil materinya.","s":1}], "ex":"Kiriman propaganda teroris wajib ditahan dan dilaporkan ke aparat keamanan."},
{"id":"TKP-3507", "q":"Rest area tol dipakai sekelompok orang untuk menyebarkan selebaran paham khilafah ke pengendara. Anda pengelola. Tindakan Anda?", "opts":[{"t":"Mengusir penyebar dan berkoordinasi dengan aparat keamanan.","s":5},{"t":"Menegur dan menyita selebarannya.","s":4},{"t":"Membiarkan karena area ramai.","s":3},{"t":"Menganggapnya bukan wewenang.","s":2},{"t":"Ikut membagikan selebaran.","s":1}], "ex":"Fasilitas publik wajib steril dari propaganda khilafah; pengelola wajib menindak."},
{"id":"TKP-3508", "q":"Balai pemasyarakatan menemukan klien yang menyebarkan paham ekstrem ke klien lain. Anda pembimbing. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pimpinan agar pelaku dibina khusus dan dipisahkan.","s":5},{"t":"Memberi pembinaan intensif tentang bahayanya.","s":4},{"t":"Menganggapnya urusan antar-klien.","s":3},{"t":"Membiarkan karena takut.","s":2},{"t":"Ikut mendengarkan ceramahnya.","s":1}], "ex":"Penyebaran paham ekstrem di balai pemasyarakatan wajib ditindak lewat pembinaan resmi."},
{"id":"TKP-3509", "q":"Klinik keliling (mobile) dipakai oknum untuk menyebarkan paham intoleran ke pasien di desa. Anda nakes. Sikap Anda?", "opts":[{"t":"Melaporkan ke dinas kesehatan/aparat agar ditindak.","s":5},{"t":"Menegur oknum agar fokus pada layanan kesehatan.","s":4},{"t":"Diam karena bukan wewenang.","s":3},{"t":"Membiarkan dengan alasan program jalan.","s":2},{"t":"Ikut menyebarkan pahamnya.","s":1}], "ex":"Layanan kesehatan keliling tidak boleh disusupi paham intoleran; wajib dilaporkan."},
{"id":"TKP-3510", "q":"Kernet bus antarkota memutar video propaganda kelompok teroris yang mengagungkan kekerasan. Anda penumpang. Sikap Anda?", "opts":[{"t":"Meminta dimatikan dan melaporkan ke perusahaan otobus/aparat.","s":5},{"t":"Menegur kernet agar mengganti tontonan.","s":4},{"t":"Diam dan memakai earphone.","s":3},{"t":"Membiarkan karena menghormati.","s":2},{"t":"Ikut menonton dengan antusias.","s":1}], "ex":"Propaganda teroris di angkutan umum wajib ditolak; penumpang berhak menuntut dan melapor."},
{"id":"TKP-3511", "q":"KUD diminta menyalurkan bantuan pupuk bersubsidi lewat kelompok yang menyebarkan paham khilafah. Anda pengurus. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke dinas pertanian/aparat.","s":5},{"t":"Menolak dengan alasan penyaluran harus resmi.","s":4},{"t":"Menyalurkan karena desakan.","s":3},{"t":"Menyalurkan demi kelancaran.","s":2},{"t":"Ikut bergabung kelompok itu.","s":1}], "ex":"Bantuan negara tidak boleh disalurkan lewat kelompok paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3512", "q":"Panitia zakat fitrah ketahuan menyalurkan sebagian zakat ke jaringan kelompok ekstrem. Anda muzakki. Sikap Anda?", "opts":[{"t":"Melaporkan penyelewengan itu ke takmir/aparat.","s":5},{"t":"Menuntut transparansi penyaluran zakat.","s":4},{"t":"Berhenti berzakat di sana tanpa protes.","s":3},{"t":"Tetap berzakat dengan alasan niat.","s":2},{"t":"Ikut menggalang untuk penyaluran itu.","s":1}], "ex":"Dana zakat yang diselewengkan ke jaringan ekstrem wajib dilaporkan; transparansi wajib dituntut."},
{"id":"TKP-3513", "q":"Turnamen sepak bola tarkam disusupi spanduk dan orasi paham intoleran oleh suporter. Anda panitia. Tindakan Anda?", "opts":[{"t":"Menurunkan spanduk, menghentikan orasi, dan melaporkan ke aparat.","s":5},{"t":"Menegur suporter agar fokus pada pertandingan.","s":4},{"t":"Membiarkan karena suporter ramai.","s":3},{"t":"Menganggapnya bagian kemeriahan.","s":2},{"t":"Ikut berorasi mendukung.","s":1}], "ex":"Ajang olahraga tidak boleh disusupi paham intoleran; panitia wajib menertibkan dan melapor."},
{"id":"TKP-3514", "q":"Koran dinding kampus ditempeli artikel propaganda khilafah oleh sekelompok mahasiswa. Anda dosen. Tindakan Anda?", "opts":[{"t":"Mencopot artikel dan membina mahasiswa serta melaporkan ke pimpinan kampus.","s":5},{"t":"Menegur mahasiswa dan memberi pembinaan wawasan kebangsaan.","s":4},{"t":"Membiarkan karena karya mahasiswa.","s":3},{"t":"Menganggapnya kebebasan akademik.","s":2},{"t":"Ikut memajang artikel serupa.","s":1}], "ex":"Kampus wajib steril dari propaganda khilafah; dosen harus menertibkan dan membina."},
{"id":"TKP-3515", "q":"Pelaut Indonesia diajak ABK asing bergabung jaringan kelompok ekstrem internasional yang anti-NKRI. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke nakhoda/perwakilan RI.","s":5},{"t":"Menolak dan memperingatkan pelaut Indonesia lain.","s":4},{"t":"Menolak diam-diam.","s":3},{"t":"Ikut agar tidak dikucilkan di kapal.","s":2},{"t":"Aktif bergabung jaringannya.","s":1}], "ex":"Pelaut Indonesia tidak boleh direkrut jaringan anti-NKRI; wajib ditolak dan dilaporkan."},
{"id":"TKP-3516", "q":"Lelang amal untuk korban bencana ternyata hasilnya disalurkan ke kelompok berpaham ekstrem. Anda peserta lelang. Sikap Anda?", "opts":[{"t":"Melaporkan penyaluran itu ke panitia/aparat.","s":5},{"t":"Menuntut transparansi hasil lelang.","s":4},{"t":"Tidak ikut lelang lagi.","s":3},{"t":"Tetap ikut karena barangnya bagus.","s":2},{"t":"Ikut menggalang lelang itu.","s":1}], "ex":"Dana amal yang disalurkan ke paham ekstrem wajib dilaporkan; transparansi wajib dituntut."},
{"id":"TKP-3517", "q":"BP4 (badan penasihatan perkawinan) menemukan pasangan binaan yang suaminya memaksa istri ikut kelompok anti-NKRI yang berpaham radikal. Anda konselor. Tindakan Anda?", "opts":[{"t":"Memberi konseling perlindungan dan melaporkan indikasi itu ke aparat.","s":5},{"t":"Menasihati suami agar menghentikan pemaksaan.","s":4},{"t":"Menganggapnya urusan rumah tangga.","s":3},{"t":"Mendukung suami demi keutuhan.","s":2},{"t":"Ikut membenarkan kelompok itu.","s":1}], "ex":"Pemaksaan ikut kelompok anti-NKRI adalah kekerasan; konselor wajib melindungi dan melapor."},
{"id":"TKP-3518", "q":"Pendata bansos menemukan satu keluarga yang menolak bantuan karena menganggap program pemerintah 'thagut' akibat doktrin ekstrem. Sikap Anda?", "opts":[{"t":"Mencatat temuan dan melaporkan indikasi doktrin itu ke koordinator/aparat.","s":5},{"t":"Memberi edukasi tentang program pemerintah.","s":4},{"t":"Mencoret keluarga itu dari daftar.","s":3},{"t":"Memaksa menerima bantuan.","s":2},{"t":"Ikut membenarkan penolakannya.","s":1}], "ex":"Penolakan berlabel ekstrem wajib dicatat dan dilaporkan; pendata tetap edukatif."},
{"id":"TKP-3519", "q":"Rumah tahfidz di lingkungan Anda disusupi pengajar yang menanamkan paham intoleran kepada santrinya. Anda warga. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola dan Kemenag/aparat.","s":5},{"t":"Menegur pengelola agar mengevaluasi pengajar.","s":4},{"t":"Tidak menyekolahkan anak ke sana.","s":3},{"t":"Membiarkan karena urusan yayasan.","s":2},{"t":"Ikut mendukung pengajarnya.","s":1}], "ex":"Rumah tahfidz tidak boleh disusupi paham intoleran; warga wajib melapor ke pihak berwenang."},
{"id":"TKP-3520", "q":"Jagawana menemukan perambah hutan yang ternyata juga menyebarkan paham ekstrem ke warga sekitar hutan. Tindakan Anda?", "opts":[{"t":"Menindak perambahan dan melaporkan penyebaran paham ke aparat.","s":5},{"t":"Menegur dan mengusir perambah dari kawasan.","s":4},{"t":"Fokus pada perambahan saja.","s":3},{"t":"Membiarkan karena takut.","s":2},{"t":"Ikut mendengarkan ceramahnya.","s":1}], "ex":"Penyebaran paham ekstrem di kawasan hutan wajib dilaporkan bersama penindakan perambahan."},
{"id":"TKP-3521", "q":"Kelompok yasinan diajak tahlil keliling yang ternyata dimanfaatkan untuk orasi paham khilafah. Anda anggota. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menasihati koordinator agar menghentikan pemanfaatan itu.","s":4},{"t":"Tidak ikut tanpa penjelasan.","s":3},{"t":"Ikut yasinan tanpa peduli orasinya.","s":2},{"t":"Ikut berorasi mendukung.","s":1}], "ex":"Kegiatan keagamaan tidak boleh dimanfaatkan untuk orasi paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3522", "q":"Sopir travel mengajak penumpangnya mampir ke 'pesantren' yang ternyata pusat indoktrinasi paham ekstrem. Anda penumpang. Sikap Anda?", "opts":[{"t":"Menolak mampir dan melaporkan ke perusahaan travel/aparat.","s":5},{"t":"Menegur sopir agar fokus pada perjalanan.","s":4},{"t":"Tetap ikut karena sudah termasuk rute.","s":3},{"t":"Mampir sekadar istirahat.","s":2},{"t":"Ikut kajian di dalamnya.","s":1}], "ex":"Jasa travel tidak boleh dialihkan untuk indoktrinasi paham ekstrem; wajib ditolak dan dilaporkan."},
{"id":"TKP-3523", "q":"Kantin kampus memutar ceramah intoleran yang provokatif setiap jam makan. Anda mahasiswa. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola kampus agar ditertibkan.","s":5},{"t":"Meminta pengelola mengganti tontonan.","s":4},{"t":"Makan di tempat lain.","s":3},{"t":"Membiarkan karena ramai.","s":2},{"t":"Ikut menonton dengan antusias.","s":1}], "ex":"Fasilitas kampus wajib steril dari ceramah intoleran; mahasiswa berhak menuntut penertiban."},
{"id":"TKP-3524", "q":"Satpam mal diminta membiarkan penyebaran selebaran propaganda teroris di area parkir. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke manajemen mal/aparat.","s":5},{"t":"Menolak dan mengusir penyebar selebaran.","s":4},{"t":"Membiarkan karena takut.","s":3},{"t":"Membiarkan dengan alasan bukan wewenang.","s":2},{"t":"Ikut membagikan selebaran.","s":1}], "ex":"Area publik tidak boleh dipakai menyebar propaganda teroris; satpam wajib menolak dan melapor."},
{"id":"TKP-3525", "q":"Mahasiswa magang kampus merdeka di instansi Anda menyebarkan paham khilafah ke grup pegawai. Anda mentor. Tindakan Anda?", "opts":[{"t":"Menegur, membina, dan melaporkan ke kampus/instansi bila berlanjut.","s":5},{"t":"Memberi pembinaan wawasan kebangsaan langsung.","s":4},{"t":"Mengeluarkannya dari grup saja.","s":3},{"t":"Membiarkan karena ia mahasiswa.","s":2},{"t":"Ikut mendiskusikan pahamnya.","s":1}], "ex":"Mentor wajib membina mahasiswa magang yang menyebar paham khilafah, bukan membiarkannya."}
,
{"id":"TKP-3526", "q":"Cleaning service mal diminta menempelkan stiker propaganda ekstrem di toilet mal. Sikap Anda?", "opts":[{"t":"Menolak menempel dan melaporkan perintah itu ke atasan.","s":5},{"t":"Menolak dengan alasan bukan tugasnya.","s":4},{"t":"Menempel karena takut dipecat.","s":3},{"t":"Menempel dengan alasan perintah.","s":2},{"t":"Ikut menyebarkan stikernya.","s":1}], "ex":"Fasilitas publik tidak boleh ditempeli propaganda ekstrem; perintah wajib ditolak dan dilaporkan."},
{"id":"TKP-3527", "q":"Operator sekolah diajak admin grup menyebarkan ujaran intoleran ke grup orang tua murid. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke kepala sekolah.","s":5},{"t":"Menolak dan menjaga grup tetap netral.","s":4},{"t":"Diam tanpa memihak.","s":3},{"t":"Ikut menyebar agar diterima.","s":2},{"t":"Aktif menyebarkan ujaran itu.","s":1}], "ex":"Grup resmi sekolah tidak boleh dipakai menyebar ujaran intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3528", "q":"Penyuluh PPPK menemukan kelompok binaannya diajak baiat paham intoleran. Tindakan Anda?", "opts":[{"t":"Mencegah dan melaporkan ke atasan/aparat.","s":5},{"t":"Memberi penyuluhan tandingan tentang bahayanya.","s":4},{"t":"Fokus pada materi penyuluhan saja.","s":3},{"t":"Membiarkan karena di luar tugas.","s":2},{"t":"Ikut menghadiri baiatnya.","s":1}], "ex":"Kelompok binaan tidak boleh dibaiat paham intoleran; penyuluh wajib mencegah dan melapor."},
{"id":"TKP-3529", "q":"Pemeriksa internal BUMD menemukan dana CSR mengalir ke organisasi berpaham ekstrem. Direksi meminta temuan dihapus. Sikap Anda?", "opts":[{"t":"Tetap melaporkan temuan ke dewan pengawas/aparat.","s":5},{"t":"Mencatat temuan resmi dan menolak menghapusnya.","s":4},{"t":"Mengikuti perintah direksi.","s":3},{"t":"Menghapus temuan.","s":2},{"t":"Ikut menutupi aliran dana.","s":1}], "ex":"Temuan dana ke paham ekstrem tidak boleh dihapus atas perintah siapa pun; wajib dilaporkan."},
{"id":"TKP-3530", "q":"Penyuluh kehutanan menemukan warga sekitar hutan diajak kelompok ekstrem untuk memusuhi petugas. Tindakan Anda?", "opts":[{"t":"Melaporkan ke atasan dan berkoordinasi dengan aparat keamanan.","s":5},{"t":"Memberi penyuluhan tentang bahaya paham tersebut.","s":4},{"t":"Fokus pada materi kehutanan saja.","s":3},{"t":"Membiarkan karena takut.","s":2},{"t":"Ikut mendengarkan ajakannya.","s":1}], "ex":"Warga hutan tidak boleh dihasut memusuhi petugas; temuan wajib dilaporkan dan dikoordinasikan."},
{"id":"TKP-3531", "q":"Danramil menerima laporan adanya latihan fisik mencurigakan berkedok bela diri yang terindikasi persiapan aksi teror. Tindakan Anda?", "opts":[{"t":"Menindaklanjuti dengan penyelidikan dan koordinasi ke kepolisian/BNPT.","s":5},{"t":"Mendatangi lokasi untuk verifikasi awal.","s":4},{"t":"Mencatat tanpa tindak lanjut.","s":3},{"t":"Menganggapnya latihan biasa.","s":2},{"t":"Membocorkan rencana penyelidikan.","s":1}], "ex":"Latihan mencurigakan terindikasi persiapan teror wajib diselidiki aparat lewat koordinasi resmi."},
{"id":"TKP-3532", "q":"Staf desa diminta memasukkan nama-nama simpatisan kelompok khilafah sebagai penerima bantuan. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke kepala desa/camat.","s":5},{"t":"Menolak dengan alasan data harus sesuai kriteria.","s":4},{"t":"Memasukkan karena perintah.","s":3},{"t":"Memasukkan agar aman.","s":2},{"t":"Ikut mendata simpatisannya.","s":1}], "ex":"Bantuan negara tidak boleh dipakai untuk simpatisan paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3533", "q":"Operator desa diminta mengunggah konten propaganda intoleran ke media sosial resmi desa. Sikap Anda?", "opts":[{"t":"Menolak mengunggah dan melaporkan ke kepala desa.","s":5},{"t":"Menolak dengan alasan medsos desa untuk informasi resmi.","s":4},{"t":"Mengunggah karena perintah.","s":3},{"t":"Mengunggah agar tidak dimarahi.","s":2},{"t":"Ikut membuat kontennya.","s":1}], "ex":"Medsos resmi desa tidak boleh dipakai untuk propaganda intoleran; wajib ditolak dan dilaporkan."},
{"id":"TKP-3534", "q":"Forum anak desa diajak mengikuti 'pelatihan' yang ternyata indoktrinasi paham ekstrem. Anda pendamping forum. Sikap Anda?", "opts":[{"t":"Membatalkan keikutsertaan dan melaporkan penyelenggaranya.","s":5},{"t":"Menarik anak-anak dari kegiatan itu.","s":4},{"t":"Membiarkan karena pesertanya antusias.","s":3},{"t":"Menganggapnya pelatihan biasa.","s":2},{"t":"Ikut mendukung penyelenggaranya.","s":1}], "ex":"Anak-anak tidak boleh diindoktrinasi paham ekstrem; pendamping wajib bertindak dan melapor."},
{"id":"TKP-3535", "q":"Jaga malam pasar diminta membiarkan penyebaran selebaran propaganda teroris di area pasar. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke pengelola pasar/aparat.","s":5},{"t":"Menolak dan mengusir penyebar selebaran.","s":4},{"t":"Membiarkan karena takut.","s":3},{"t":"Membiarkan dengan alasan bukan wewenang.","s":2},{"t":"Ikut membagikan selebaran.","s":1}], "ex":"Pasar wajib steril dari propaganda teroris; petugas jaga wajib menolak dan melapor."},
{"id":"TKP-3536", "q":"Dewan kemakmuran masjid ditekan agar dana umat dipakai membiayai orasi kelompok intoleran. Sikap Anda sebagai pengurus?", "opts":[{"t":"Menolak tekanan dan melaporkan ke DMI/aparat.","s":5},{"t":"Menolak dengan alasan dana untuk kemakmuran masjid.","s":4},{"t":"Menyerahkan sebagian agar tidak ribut.","s":3},{"t":"Menyerahkan karena takut.","s":2},{"t":"Ikut menggalang dana orasi.","s":1}], "ex":"Dana umat tidak boleh dipakai untuk orasi paham intoleran; tekanan wajib ditolak dan dilaporkan."},
{"id":"TKP-3537", "q":"Pura didatangi kelompok intoleran yang menuntut pembatasan upacara keagamaan. Anda pengurus pura. Sikap Anda?", "opts":[{"t":"Menolak tuntutan dan melaporkan ke aparat penegak hukum.","s":5},{"t":"Berkoordinasi dengan aparat untuk pengamanan.","s":4},{"t":"Mengurangi upacara agar aman.","s":3},{"t":"Menuruti tuntutan demi keamanan.","s":2},{"t":"Ikut membenarkan tuntutan.","s":1}], "ex":"Kebebasan beribadah dilindungi undang-undang; tuntutan intoleran wajib ditolak dan dilaporkan."},
{"id":"TKP-3538", "q":"Kepala suku diminta memberikan tanah adat untuk markas kelompok berpaham khilafah. Sikap Anda?", "opts":[{"t":"Menolak memberikan dan melaporkan ke aparat.","s":5},{"t":"Menolak dengan alasan tanah untuk kepentingan adat.","s":4},{"t":"Memberikan agar tidak berkonflik.","s":3},{"t":"Memberikan karena dijanjikan imbalan.","s":2},{"t":"Ikut menjadi pelindung markas.","s":1}], "ex":"Tanah adat tidak boleh dipakai untuk markas paham khilafah; tokoh adat wajib menolak dan melapor."},
{"id":"TKP-3539", "q":"Aktivis kampus diajak menjadi humas jaringan kelompok ekstrem yang anti-pemerintah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan itu ke aparat kampus/kepolisian.","s":5},{"t":"Menolak dan memperingatkan aktivis lain.","s":4},{"t":"Menolak halus tanpa melapor.","s":3},{"t":"Menerima karena iming-iming popularitas.","s":2},{"t":"Aktif menjadi humasnya.","s":1}], "ex":"Aktivis kampus tidak boleh menjadi humas paham ekstrem; ajakan wajib ditolak dan dilaporkan."},
{"id":"TKP-3540", "q":"OSIS diajak mengikuti 'LDK' yang ternyata ajang indoktrinasi paham intoleran. Anda pembina OSIS. Sikap Anda?", "opts":[{"t":"Membatalkan keikutsertaan dan melaporkan penyelenggaranya.","s":5},{"t":"Menarik siswa dari kegiatan itu.","s":4},{"t":"Membiarkan karena pesertanya antusias.","s":3},{"t":"Menganggapnya LDK biasa.","s":2},{"t":"Ikut mendukung penyelenggaranya.","s":1}], "ex":"OSIS tidak boleh dijadikan ajang indoktrinasi intoleran; pembina wajib bertindak dan melapor."},
{"id":"TKP-3541", "q":"Muslimat diajak menggalang dana untuk 'janda mujahid' yang ternyata keluarga teroris. Anda anggota. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan penggalangan itu ke aparat.","s":5},{"t":"Menasihati penggagas agar menghentikan.","s":4},{"t":"Tidak ikut tanpa protes.","s":3},{"t":"Ikut menyumbang karena kasihan.","s":2},{"t":"Ikut menggalang dana.","s":1}], "ex":"Dana untuk keluarga teroris adalah pendanaan terorisme; wajib ditolak dan dilaporkan."},
{"id":"TKP-3542", "q":"BKB (bina keluarga balita) disusupi pembagian susu gratis yang diselingi ceramah doktrin ekstrem. Anda kader. Tindakan Anda?", "opts":[{"t":"Menghentikan kegiatan dan melaporkan ke puskesmas/aparat.","s":5},{"t":"Menegur penyelenggara agar fokus pada kesehatan balita.","s":4},{"t":"Tetap membagikan susunya.","s":3},{"t":"Menganggapnya bonus penyuluhan.","s":2},{"t":"Ikut menyebarkan ceramahnya.","s":1}], "ex":"Layanan balita tidak boleh ditunggangi doktrin ekstrem; kader wajib menghentikan dan melapor."},
{"id":"TKP-3543", "q":"Kader Jumantik diminta mendata rumah warga untuk 'pemetaan dakwah' kelompok berpaham khilafah. Sikap Anda?", "opts":[{"t":"Menolak mendata dan melaporkan ke koordinator/aparat.","s":5},{"t":"Menolak dengan alasan tugas jumantik hanya jentik nyamuk.","s":4},{"t":"Mendata sebagian agar tidak dimusuhi.","s":3},{"t":"Mendata karena perintah.","s":2},{"t":"Aktif membantu pemetaan.","s":1}], "ex":"Tugas kesehatan tidak boleh dipakai untuk pemetaan paham khilafah; wajib ditolak dan dilaporkan."},
{"id":"TKP-3544", "q":"Daycare disusupi pengasuh yang mengajarkan ujaran intoleran kepada anak asuh. Anda orang tua. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola daycare dan dinas terkait.","s":5},{"t":"Menegur pengelola agar mengganti pengasuh.","s":4},{"t":"Memindahkan anak tanpa protes.","s":3},{"t":"Membiarkan karena anak masih kecil.","s":2},{"t":"Ikut mendukung pengasuhnya.","s":1}], "ex":"Anak asuh wajib dilindungi dari ujaran intoleran; orang tua wajib melapor."},
{"id":"TKP-3545", "q":"Qori yang Anda undang ternyata dalam tausiahnya yang intoleran menghasut jamaah memusuhi kelompok berbeda paham. Anda panitia. Sikap Anda?", "opts":[{"t":"Menghentikan tausiah dan melaporkan ke aparat.","s":5},{"t":"Menegur qori agar menghentikan hasutannya.","s":4},{"t":"Membiarkan sampai selesai karena sudah dibayar.","s":3},{"t":"Menganggapnya gaya tausiah biasa.","s":2},{"t":"Ikut menyebarkan rekamannya.","s":1}], "ex":"Tausiah tidak boleh berisi hasutan memusuhi beda paham; panitia wajib menghentikan dan melapor."},
{"id":"TKP-3546", "q":"Ajengan diajak menjadi 'guru spiritual' kelompok yang menyebarkan paham khilafah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan itu ke aparat.","s":5},{"t":"Menolak dengan alasan menjaga kemurnian dakwah.","s":4},{"t":"Menerima karena menghormati yang mengajak.","s":3},{"t":"Menerima demi memperluas jamaah.","s":2},{"t":"Aktif menjadi gurunya.","s":1}], "ex":"Ulama tidak boleh menjadi guru paham khilafah; ajakan wajib ditolak dan dilaporkan."},
{"id":"TKP-3547", "q":"Pastor didatangi kelompok intoleran yang menuntut pembatasan kegiatan gereja. Anda umat yang mengetahui. Sikap Anda?", "opts":[{"t":"Mendukung pastor menolak dan melaporkan ke aparat.","s":5},{"t":"Berkoordinasi dengan aparat untuk pengamanan.","s":4},{"t":"Meminta kegiatan dikurangi agar aman.","s":3},{"t":"Menuruti tuntutan demi keamanan.","s":2},{"t":"Ikut membenarkan tuntutan.","s":1}], "ex":"Kebebasan beribadah dilindungi; tuntutan intoleran wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-3548", "q":"LKSA (lembaga kesejahteraan sosial anak) menerima 'donatur' yang mensyaratkan anak asuh mengikuti pembinaan berpaham ekstrem. Anda pengurus. Sikap Anda?", "opts":[{"t":"Menolak donasi dan melaporkan ke dinas sosial/aparat.","s":5},{"t":"Menolak syaratnya dan mencari donatur lain.","s":4},{"t":"Menerima karena butuh dana.","s":3},{"t":"Menerima dengan alasan keterpaksaan.","s":2},{"t":"Ikut menjalankan pembinaannya.","s":1}], "ex":"Anak asuh tidak boleh dieksploitasi paham ekstrem lewat donasi; wajib ditolak dan dilaporkan."},
{"id":"TKP-3549", "q":"Yayasan masjid ditekan agar menyerahkan pengelolaan khutbah kepada kelompok intoleran. Anda pengurus yayasan. Sikap Anda?", "opts":[{"t":"Menolak tekanan dan melaporkan ke DMI/aparat.","s":5},{"t":"Menolak dengan alasan khutbah kewenangan yayasan.","s":4},{"t":"Menyerahkan sebagian jadwal agar tidak ribut.","s":3},{"t":"Menyerahkan karena takut.","s":2},{"t":"Ikut mengundang penceramahnya.","s":1}], "ex":"Pengelolaan khutbah tidak boleh direbut kelompok intoleran; tekanan wajib ditolak dan dilaporkan."},
{"id":"TKP-3550", "q":"Bilal diminta mengumandangkan seruan provokatif bernada intoleran sebelum adzan. Sikap Anda sebagai bilal?", "opts":[{"t":"Menolak dan melaporkan permintaan itu ke takmir/aparat.","s":5},{"t":"Menolak dengan alasan pengeras suara untuk adzan.","s":4},{"t":"Menuruti sekali agar tidak dimusuhi.","s":3},{"t":"Menuruti karena perintah pengurus.","s":2},{"t":"Ikut mengumandangkan dengan semangat.","s":1}], "ex":"Pengeras suara masjid tidak boleh dipakai untuk provokasi intoleran; wajib ditolak dan dilaporkan."}
]
